            pos += 1

            # Check for range
            if pos < len(pattern) and pattern[pos] == '-' and pos + 1 < len(pattern) and pattern[pos + 1] != ']':
                pos += 1  # consume '-'
                end_ch = pattern[pos]
                pos += 1
                ranges.append(('range', ch, end_ch))
            else:
                ranges.append(('char', ch))

