        raise ValueError("Unclosed character class")

    pos += 1  # consume ']'

    return ('class', negated, ranges), pos


def parse_group(pattern, pos):
    """Parse group (...)."""
    if pos >= len(pattern) or pattern[pos] != '(':
        raise ValueError("Expected '('")

    pos += 1
    inner, pos = parse_alternation(pattern, pos)

    if pos >= len(pattern) or pattern[pos] != ')':
        raise ValueError("Unclosed group")

    pos += 1
    return ('group', inner), pos


def match_pattern(parsed, text, text_pos):
    """
    Match pattern against text starting at text_pos.
    Returns the position in text after matching, or -1 if no match.
    """
    if isinstance(parsed, tuple):
        if parsed[0] == 'literal':
            if text_pos < len(text) and text[text_pos] == parsed[1]:
                return text_pos + 1
            return -1

        elif parsed[0] == 'dot':
            if text_pos < len(text):
                return text_pos + 1
            return -1

        elif parsed[0] == 'anchor':
            if parsed[1] == '^':
                return text_pos if text_pos == 0 else -1
            elif parsed[1] == '$':
                return text_pos if text_pos == len(text) else -1

        elif parsed[0] == 'class':
            if text_pos >= len(text):
                return -1
            ch = text[text_pos]
            negated, ranges = parsed[1], parsed[2]
            matches = char_in_class(ch, ranges)
            if matches != negated:
                return text_pos + 1
            return -1

        elif parsed[0] == 'sequence':
            pos = text_pos
            for atom in parsed[1]:
                result = match_pattern(atom, text, pos)
                if result == -1:
                    return -1
                pos = result
            return pos

        elif parsed[0] == 'quantifier':
            quantifier, atom = parsed[1], parsed[2]
            return match_quantifier(quantifier, atom, text, text_pos)

        elif parsed[0] == 'group':
            return match_pattern(parsed[1], text, text_pos)

        elif parsed[0] == 'alternation':
            for alternative in parsed[1]:
                result = match_pattern(alternative, text, text_pos)
                if result != -1:
                    return result
            return -1

    return -1


def match_quantifier(quantifier, atom, text, text_pos):
    """Match quantified atom with backtracking."""
    if quantifier == '*':
        # Zero or more: collect all possible match lengths and try each
        return match_with_backtrack(atom, text, text_pos, 0, None)
    elif quantifier == '+':
        # One or more: must match at least once
        result = match_pattern(atom, text, text_pos)
        if result == -1:
            return -1
        return match_with_backtrack(atom, text, result, 1, None)
    elif quantifier == '?':
        # Zero or one: try matching first, then no match
        result = match_pattern(atom, text, text_pos)
        if result != -1:
            return result
        return text_pos

    return -1


def match_with_backtrack(atom, text, text_pos, count, min_count):
    """
    Match quantified atom with proper backtracking.
    Tries to match greedily, but backtracks to allow rest of pattern to match.
    Returns the position after matching, or -1 if no match.
    """
    # Try to match one more occurrence of the atom
    result = match_pattern(atom, text, text_pos)

    if result != -1 and result > text_pos:
        # Successfully matched one more time
        # Recursively try to match even more
        further = match_with_backtrack(atom, text, result, count + 1, min_count)
        if further != -1:
            return further
        # Backtrack: return current position (we matched count times)
        return text_pos

    # Can't match more, return current position
    return text_pos


def char_in_class(ch, ranges):
    """Check if character is in the given ranges."""
    for item in ranges:
        if item[0] == 'char':
            if ch == item[1]:
                return True
        elif item[0] == 'range':
            start, end = item[1], item[2]
            if ord(start) <= ord(ch) <= ord(end):
                return True
    return False

