class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def current_token(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self, expected=None):
        token = self.current_token()
        if expected is not None and token != expected:
            raise ValueError(f"Expected {expected}, got {token}")
        self.pos += 1
        return token

    def parse_expression(self):
        """Parse addition and subtraction (lowest precedence)"""
        left = self.parse_term()

        while self.current_token() in ('+', '-'):
            op = self.consume()
            right = self.parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right

        return left

    def parse_term(self):
        """Parse multiplication, division, modulo (middle precedence)"""
        left = self.parse_unary()

        while self.current_token() in ('*', '/', '%'):
            op = self.consume()
            right = self.parse_unary()
            if op == '*':
                left = left * right
            elif op == '/':
                if right == 0:
                    raise ValueError("Division by zero")
                left = left / right
            else:  # op == '%'
                if right == 0:
                    raise ValueError("Modulo by zero")
                left = left % right

        return left

    def parse_unary(self):
        """Parse unary operators (minus and plus)"""
        if self.current_token() in ('+', '-'):
            op = self.consume()
            operand = self.parse_unary()
            if op == '-':
                return -operand
            else:
                return operand

        return self.parse_power()

    def parse_power(self):
        """Parse exponentiation (right-associative, highest precedence)"""
        left = self.parse_primary()

        if self.current_token() == '**':
            self.consume()
            # Right-associative: parse the right side with unary operators
            right = self.parse_unary()
            return left ** right

        return left

