        if isinstance(token, (int, float)):
            self.consume()
            return float(token)

        raise ValueError(f"Invalid token: {token}")


def tokenize(expr: str):
    """Tokenize the expression into a list of tokens"""
    if not expr or expr.isspace():
        raise ValueError("Empty expression")

    tokens = []
    i = 0

    while i < len(expr):
