import threading


class Bank:
    def __init__(self):
        self._lock = threading.Lock()
        self._accounts = {}  # acc_id -> balance

    def create_account(self, acc_id: str) -> None:
        """Create a new account with zero balance. Raises ValueError if account already exists."""
        with self._lock:
            if acc_id in self._accounts:
                raise ValueError(f"Account {acc_id} already exists")
            self._accounts[acc_id] = 0.0

    def deposit(self, acc_id: str, amount: float) -> None:
        """Deposit amount into account. Raises ValueError if amount <= 0 or account missing."""
        if amount <= 0:
            raise ValueError(f"Deposit amount must be positive, got {amount}")

        with self._lock:
            if acc_id not in self._accounts:
                raise ValueError(f"Account {acc_id} does not exist")
            self._accounts[acc_id] += amount

    def withdraw(self, acc_id: str, amount: float) -> None:
        """Withdraw amount from account. Raises ValueError if amount <= 0, account missing, or insufficient balance."""
        if amount <= 0:
            raise ValueError(f"Withdrawal amount must be positive, got {amount}")

        with self._lock:
            if acc_id not in self._accounts:
                raise ValueError(f"Account {acc_id} does not exist")
            if self._accounts[acc_id] < amount:
                raise ValueError(f"Insufficient balance in account {acc_id}")
            self._accounts[acc_id] -= amount

    def transfer(self, from_id: str, to_id: str, amount: float) -> None:
        """Atomically transfer amount from one account to another. 
        Raises ValueError if amount <= 0, either account missing, or insufficient funds.
        If transfer fails, nothing changes."""
        if amount <= 0:
            raise ValueError(f"Transfer amount must be positive, got {amount}")

        with self._lock:
            # Check both accounts exist
            if from_id not in self._accounts:
                raise ValueError(f"Account {from_id} does not exist")
            if to_id not in self._accounts:
                raise ValueError(f"Account {to_id} does not exist")

            # Check sufficient balance
            if self._accounts[from_id] < amount:
                raise ValueError(f"Insufficient balance in account {from_id}")

            # Perform atomic transfer
            self._accounts[from_id] -= amount
            self._accounts[to_id] += amount

    def balance(self, acc_id: str) -> float:
        """Get the balance of an account. Raises ValueError if account missing."""
        with self._lock:
            if acc_id not in self._accounts:
                raise ValueError(f"Account {acc_id} does not exist")
            return self._accounts[acc_id]

def bencode(obj: object) -> bytes:
    """Encode a Python object to bencode format (bytes)."""
    if isinstance(obj, bool) or isinstance(obj, type(None)):
        raise ValueError(f"Cannot bencode {type(obj).__name__}")

    if isinstance(obj, int):
        return f'i{obj}e'.encode('ascii')

    if isinstance(obj, bytes):
        return f'{len(obj)}:'.encode('ascii') + obj

    if isinstance(obj, str):
        encoded = obj.encode('utf-8')
        return f'{len(encoded)}:'.encode('ascii') + encoded

    if isinstance(obj, list):
        result = b'l'
        for item in obj:
            result += bencode(item)
        result += b'e'
        return result

    if isinstance(obj, dict):
        result = b'd'
        # Sort keys lexicographically by their encoded bytes
        items = []
        for key, value in obj.items():
            if not isinstance(key, str):
                raise ValueError(f"Dict keys must be str, got {type(key).__name__}")
            encoded_key = key.encode('utf-8')
            items.append((encoded_key, bencode(value)))

        # Sort by encoded key bytes
        items.sort(key=lambda x: x[0])

        for encoded_key, encoded_value in items:
            result += f'{len(encoded_key)}:'.encode('ascii') + encoded_key + encoded_value
        result += b'e'
        return result

    raise ValueError(f"Cannot bencode {type(obj).__name__}")


def bdecode(data: bytes) -> object:
    """Decode bencode format (bytes) to a Python object."""
    if not data:
        raise ValueError("Empty input")

    obj, pos = _decode_value(data, 0)

    # Check for trailing data
    if pos != len(data):
        raise ValueError("Trailing data after value")

    return obj


def _decode_value(data: bytes, pos: int) -> tuple:
    """Decode a single value starting at position pos. Returns (value, new_pos)."""
    if pos >= len(data):
        raise ValueError("Unexpected end of input")

    ch = data[pos:pos+1]

    if ch == b'i':
        return _decode_int(data, pos)
    elif ch == b'l':
        return _decode_list(data, pos)
    elif ch == b'd':
        return _decode_dict(data, pos)
    elif ch.isdigit():
        return _decode_bytes(data, pos)
    else:
        raise ValueError(f"Unexpected byte: {ch}")


def _decode_int(data: bytes, pos: int) -> tuple:
    """Decode an integer (i<num>e format). Returns (int_value, new_pos)."""
    pos += 1  # skip 'i'

    if pos >= len(data):
        raise ValueError("Unterminated integer")

    start = pos

    # Handle negative sign
    if data[pos:pos+1] == b'-':
        pos += 1
        if pos >= len(data):
            raise ValueError("Unterminated integer")

    # Must have at least one digit
    if pos >= len(data) or not data[pos:pos+1].isdigit():
        raise ValueError("Invalid integer format")

    # Collect digits
    while pos < len(data) and data[pos:pos+1].isdigit():
        pos += 1

    if pos >= len(data) or data[pos:pos+1] != b'e':
        raise ValueError("Unterminated integer")

    num_str = data[start:pos].decode('ascii')

    # Check for leading zeros (except "0" itself)
    if num_str.startswith('0') and len(num_str) > 1:
        raise ValueError("Leading zeros in integer")

    # Check for "-0"
    if num_str == '-0':
        raise ValueError("Invalid integer: -0")

    # Check for bare "-"
    if num_str == '-':
        raise ValueError("Invalid integer: bare minus")

    return int(num_str), pos + 1


def _decode_bytes(data: bytes, pos: int) -> tuple:
    """Decode a byte string (<len>:<data> format). Returns (bytes_value, new_pos)."""
    start = pos

    # Check for leading zeros in length
    if data[pos:pos+1] == b'0':
        # "0:" is valid, but "0X:" where X is a digit is not
        if pos + 1 < len(data) and data[pos+1:pos+2].isdigit():
            raise ValueError("Leading zeros in length prefix")

    # Collect digits
    while pos < len(data) and data[pos:pos+1].isdigit():
        pos += 1

    if pos >= len(data) or data[pos:pos+1] != b':':
        raise ValueError("Invalid byte string format")

    length_str = data[start:pos].decode('ascii')
    length = int(length_str)

    pos += 1  # skip ':'

    # Check if we have enough data
    if pos + length > len(data):
        raise ValueError("Insufficient data for byte string")

    result = data[pos:pos+length]
    return result, pos + length


def _decode_list(data: bytes, pos: int) -> tuple:
    """Decode a list (l<items>e format). Returns (list_value, new_pos)."""
    pos += 1  # skip 'l'
    result = []

    while pos < len(data):
        if data[pos:pos+1] == b'e':
            return result, pos + 1

        item, pos = _decode_value(data, pos)
        result.append(item)

    raise ValueError("Unterminated list")


def _decode_dict(data: bytes, pos: int) -> tuple:
    """Decode a dictionary (d<key><value>...e format). Returns (dict_value, new_pos)."""
    pos += 1  # skip 'd'
    result = {}
    last_key = None

    while pos < len(data):
        if data[pos:pos+1] == b'e':
            return result, pos + 1

        # Keys must be byte strings
        if not data[pos:pos+1].isdigit():
            raise ValueError("Dict key must be a byte string")

        key, pos = _decode_bytes(data, pos)

        # Check lexicographic ordering
        if last_key is not None and key < last_key:
            raise ValueError("Dict keys not in lexicographic order")
        last_key = key

        if pos >= len(data):
            raise ValueError("Unterminated dict")

        value, pos = _decode_value(data, pos)
        result[key] = value

    raise ValueError("Unterminated dict")

def run_asm(src: str) -> str:
    """
    Assembles and executes a stack-machine program.
    Returns the concatenation of all PRINTED values (each followed by newline).
    """
    # Parse the source code into lines
    lines = src.split('\n')

    # Strip comments and whitespace, skip blank lines
    instructions = []
    for line in lines:
        # Remove comments
        if '#' in line:
            line = line[:line.index('#')]
        line = line.strip()
        if line:
            instructions.append(line)

    # First pass: collect labels
    labels = {}  # label_name -> instruction_index
    processed_instructions = []

    for instr in instructions:
        if instr.endswith(':'):
            # This is a label definition
            label_name = instr[:-1].strip()
            # Validate label name (alphanumeric + underscore)
            if not all(c.isalnum() or c == '_' for c in label_name):
                raise ValueError(f"Invalid label name: {label_name}")
            if label_name in labels:
                raise ValueError(f"Duplicate label: {label_name}")
            labels[label_name] = len(processed_instructions)
        else:
            processed_instructions.append(instr)

    # Second pass: execute instructions
    stack = []
    output = []
    pc = 0  # program counter

    while pc < len(processed_instructions):
        instr = processed_instructions[pc]
        parts = instr.split()

        if not parts:
            pc += 1
            continue

        mnemonic = parts[0]

        if mnemonic == 'PUSH':
            if len(parts) != 2:
                raise ValueError(f"PUSH requires exactly one operand")
            try:
                value = int(parts[1])
            except ValueError:
                raise ValueError(f"PUSH operand must be an integer: {parts[1]}")
            stack.append(value)

        elif mnemonic == 'POP':
            if len(parts) != 1:
                raise ValueError(f"POP takes no operands")
            if len(stack) < 1:
                raise ValueError("Stack underflow")
            stack.pop()

        elif mnemonic == 'DUP':
            if len(parts) != 1:
                raise ValueError(f"DUP takes no operands")
            if len(stack) < 1:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])

        elif mnemonic == 'SWAP':
            if len(parts) != 1:
                raise ValueError(f"SWAP takes no operands")
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            stack[-1], stack[-2] = stack[-2], stack[-1]

        elif mnemonic == 'ADD':
            if len(parts) != 1:
                raise ValueError(f"ADD takes no operands")
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)

        elif mnemonic == 'SUB':
            if len(parts) != 1:
                raise ValueError(f"SUB takes no operands")
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)

        elif mnemonic == 'MUL':
            if len(parts) != 1:
                raise ValueError(f"MUL takes no operands")
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)

        elif mnemonic == 'DIV':
            if len(parts) != 1:
                raise ValueError(f"DIV takes no operands")
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            b = stack.pop()
            a = stack.pop()
            if b == 0:
                raise ValueError("Division by zero")
            stack.append(a // b)

        elif mnemonic == 'NEG':
            if len(parts) != 1:
                raise ValueError(f"NEG takes no operands")
            if len(stack) < 1:
                raise ValueError("Stack underflow")
            stack[-1] = -stack[-1]

        elif mnemonic == 'PRINT':
            if len(parts) != 1:
                raise ValueError(f"PRINT takes no operands")
            if len(stack) < 1:
                raise ValueError("Stack underflow")
            value = stack.pop()
            output.append(str(value) + '\n')

        elif mnemonic == 'HALT':
            if len(parts) != 1:
                raise ValueError(f"HALT takes no operands")
            break

        elif mnemonic == 'JMP':
            if len(parts) != 2:
                raise ValueError(f"JMP requires exactly one operand")
            label = parts[1]
            if label not in labels:
                raise ValueError(f"Undefined label: {label}")
            pc = labels[label]
            continue

        elif mnemonic == 'JZ':
            if len(parts) != 2:
                raise ValueError(f"JZ requires exactly one operand")
            if len(stack) < 1:
                raise ValueError("Stack underflow")
            value = stack.pop()
            if value == 0:
                label = parts[1]
                if label not in labels:
                    raise ValueError(f"Undefined label: {label}")
                pc = labels[label]
                continue

        elif mnemonic == 'JNZ':
            if len(parts) != 2:
                raise ValueError(f"JNZ requires exactly one operand")
            if len(stack) < 1:
                raise ValueError("Stack underflow")
            value = stack.pop()
            if value != 0:
                label = parts[1]
                if label not in labels:
                    raise ValueError(f"Undefined label: {label}")
                pc = labels[label]
                continue

        else:
            raise ValueError(f"Unknown mnemonic: {mnemonic}")

        pc += 1

    return ''.join(output)

from typing import Set, List


class PatternError(ValueError):
    pass


class Node:
    def match(self, text: str, pos: int) -> Set[int]:
        raise NotImplementedError


class Literal(Node):
    def __init__(self, ch: str):
        self.ch = ch

    def match(self, text, pos):
        if pos < len(text) and text[pos] == self.ch:
            return {pos + 1}
        return set()


class Dot(Node):
    def match(self, text, pos):
        if pos < len(text):
            return {pos + 1}
        return set()


class CharClass(Node):
    def __init__(self, chars: Set[str], neg: bool = False):
        self.chars = set(chars)
        self.neg = neg

    def match(self, text, pos):
        if pos < len(text):
            c = text[pos]
            inside = c in self.chars
            if self.neg:
                if not inside:
                    return {pos + 1}
            else:
                if inside:
                    return {pos + 1}
        return set()


class Sequence(Node):
    def __init__(self, nodes: List[Node]):
        self.nodes = nodes

    def match(self, text, pos):
        positions = {pos}
        for node in self.nodes:
            newpos = set()
            for p in positions:
                newpos.update(node.match(text, p))
            positions = newpos
            if not positions:
                return set()
        return positions


class Alternation(Node):
    def __init__(self, options: List[Node]):
        self.options = options

    def match(self, text, pos):
        out = set()
        for opt in self.options:
            out.update(opt.match(text, pos))
        return out


class Star(Node):
    def __init__(self, node: Node):
        self.node = node

    def match(self, text, pos):
        # closure: allow zero or more repeats; avoid infinite loops by requiring progress
        results = set()
        stack = [pos]
        visited = set([pos])
        results.add(pos)
        while stack:
            cur = stack.pop()
            for nxt in self.node.match(text, cur):
                if nxt not in visited and nxt > cur:
                    visited.add(nxt)
                    results.add(nxt)
                    stack.append(nxt)
        return results


class Plus(Node):
    def __init__(self, node: Node):
        self.node = node

    def match(self, text, pos):
        first = self.node.match(text, pos)
        out = set()
        for p in first:
            # from each first-match position, apply star semantics
            out.update(Star(self.node).match(text, p))
        return out


class Question(Node):
    def __init__(self, node: Node):
        self.node = node

    def match(self, text, pos):
        out = {pos}
        out.update(self.node.match(text, pos))
        return out


class BeginAnchor(Node):
    def match(self, text, pos):
        if pos == 0:
            return {pos}
        return set()


class EndAnchor(Node):
    def match(self, text, pos):
        if pos == len(text):
            return {pos}
        return set()


def parse_pattern(pat: str) -> Node:
    i = 0
    n = len(pat)

    def parse_alternation() -> Node:
        nonlocal i
        options = [parse_sequence()]
        while i < n and pat[i] == '|':
            i += 1
            options.append(parse_sequence())
        if len(options) == 1:
            return options[0]
        return Alternation(options)

    def parse_sequence() -> Node:
        nonlocal i
        nodes: List[Node] = []
        while i < n and pat[i] not in ')|':
            node = parse_atom()
            if node is None:
                break
            # handle quantifiers
            if i < n and pat[i] in '*+?':
                q = pat[i]
                i += 1
                if q == '*':
                    node = Star(node)
                elif q == '+':
                    node = Plus(node)
                else:
                    node = Question(node)
            nodes.append(node)
        if not nodes:
            return Sequence([])
        if len(nodes) == 1:
            return nodes[0]
        return Sequence(nodes)

    def parse_atom() -> Node:
        nonlocal i
        if i >= n:
            return None
        c = pat[i]
        # anchors
        if c == '^':
            i += 1
            return BeginAnchor()
        if c == '$':
            i += 1
            return EndAnchor()
        if c == '.':
            i += 1
            return Dot()
        if c == '(':
            i += 1
            if i <= n and pat[i - 1] == '(':
                # parse group
                node = parse_alternation()
                if i >= n or pat[i] != ')':
                    raise PatternError('Unclosed group')
                i += 1
                return node
        if c == '[':
            i += 1
            if i >= n:
                raise PatternError('Unclosed character class')
            neg = False
            if pat[i] == '^':
                neg = True
                i += 1
            chars = set()
            first_in_class = True
            while i < n and pat[i] != ']':
                ch = pat[i]
                if ch == '\':
                    i += 1
                    if i >= n:
                        raise PatternError('Bad escape in class')
                    ch = pat[i]
                    chars.add(ch)
                    i += 1
                    first_in_class = False
                    continue
                # range handling
                if i + 2 < n and pat[i + 1] == '-' and pat[i + 2] != ']':
                    start = pat[i]
                    end = pat[i + 2]
                    # consume three chars
                    i += 3
                    if ord(start) <= ord(end):
                        rng = (chr(c) for c in range(ord(start), ord(end) + 1))
                    else:
                        rng = (chr(c) for c in range(ord(end), ord(start) + 1))
                    chars.update(rng)
                    first_in_class = False
                    continue
                else:
                    chars.add(ch)
                    i += 1
                    first_in_class = False
            if i >= n or pat[i] != ']':
                raise PatternError('Unclosed character class')
            i += 1
            if not chars:
                # empty class matches nothing
                return CharClass(set(), False)
            return CharClass(chars, neg)
        if c == '\':
            i += 1
            if i >= n:
                raise PatternError('Trailing backslash')
            ch = pat[i]
            i += 1
            return Literal(ch)
        # literal
        if c in '*+?':
            # quantifier without atom
            raise PatternError('Quantifier with no preceding atom')
        # normal literal
        i += 1
        return Literal(c)

    node = parse_alternation()
    if i != n:
        raise PatternError('Malformed pattern')
    return node


def full_match(pattern: str, text: str) -> bool:
    try:
        node = parse_pattern(pattern)
    except PatternError as e:
        raise ValueError(str(e))
    positions = node.match(text, 0)
    return len(text) in positions

import json
from typing import Any


def encode(obj: object) -> str:
    """Encode a Python object graph to a JSON string preserving shared references and cycles.

    Supported types: int, float, bool, None, str, list, dict (with string keys).
    """
    # Helper to check primitive supported types
    def is_primitive(o):
        return o is None or isinstance(o, (bool, int, float, str))

    # Containers we will assign ids to
    if is_primitive(obj):
        # Even if primitive, we can encode directly with empty nodes
        root = obj
        nodes = {}
        return json.dumps({"root": root, "nodes": nodes}, ensure_ascii=False)

    # Only list and dict supported as top-level non-primitive containers
    if not isinstance(obj, (list, dict)):
        raise ValueError(f"Unsupported type: {type(obj)}")

    id_map = {}  # id(obj) -> node_id
    nodes = {}  # node_id -> {"t": "list"/"dict", "v": ...}
    next_idx = 1

    def new_id():
        nonlocal next_idx
        nid = f"n{next_idx}"
        next_idx += 1
        return nid

    # assign id to root
    def assign(obj):
        oid = id(obj)
        if oid in id_map:
            return id_map[oid]
        nid = new_id()
        id_map[oid] = nid
        # create placeholder in nodes
        if isinstance(obj, list):
            nodes[nid] = {"t": "list", "v": None}
        else:
            nodes[nid] = {"t": "dict", "v": None}
        stack.append(obj)
        return nid

    stack = []
    root_id = assign(obj)

    # process stack
    while stack:
        current = stack.pop()
        cid = id_map[id(current)]
        if isinstance(current, list):
            out_list = []
            for item in current:
                if is_primitive(item):
                    out_list.append(item)
                elif isinstance(item, (list, dict)):
                    child_id = assign(item)
                    out_list.append({"$ref": child_id})
                else:
                    raise ValueError(f"Unsupported type in list: {type(item)}")
            nodes[cid]["v"] = out_list
        else:  # dict
            out_dict = {}
            for k, v in current.items():
                if not isinstance(k, str):
                    raise ValueError("Dict keys must be strings")
                if is_primitive(v):
                    out_dict[k] = v
                elif isinstance(v, (list, dict)):
                    child_id = assign(v)
                    out_dict[k] = {"$ref": child_id}
                else:
                    raise ValueError(f"Unsupported type in dict: {type(v)}")
            nodes[cid]["v"] = out_dict

    # root should be a ref to the root container
    root_rep = {"$ref": root_id}
    return json.dumps({"root": root_rep, "nodes": nodes}, ensure_ascii=False)


def decode(s: str) -> object:
    """Decode a string produced by encode back into the Python object graph.

    Raises ValueError on malformed input.
    """
    try:
        data = json.loads(s)
    except Exception as e:
        raise ValueError("Invalid JSON") from e

    if not isinstance(data, dict):
        raise ValueError("Top-level must be an object")
    if "root" not in data or "nodes" not in data:
        raise ValueError("Missing 'root' or 'nodes'")
    nodes = data["nodes"]
    root = data["root"]
    if not isinstance(nodes, dict):
        raise ValueError("'nodes' must be an object")

    # Validate node ids are strings
    for nid in nodes.keys():
        if not isinstance(nid, str):
            raise ValueError("Node ids must be strings")

    # First pass: create placeholders
    placeholders = {}
    for nid, node in nodes.items():
        if not isinstance(node, dict):
            raise ValueError("Each node must be an object")
        if "t" not in node or "v" not in node:
            raise ValueError("Node missing 't' or 'v'")
        t = node["t"]
        if t == "list":
            placeholders[nid] = []
        elif t == "dict":
            placeholders[nid] = {}
        else:
            raise ValueError("Unknown node type")

    # Helper to resolve a value
    def resolve(val):
        # A ref must be a dict with single key "$ref"
        if isinstance(val, dict) and set(val.keys()) == {"$ref"}:
            ref = val["$ref"]
            if not isinstance(ref, str):
                raise ValueError("$ref must be a string id")
            if ref not in placeholders:
                raise ValueError("Unknown $ref id")
            return placeholders[ref]
        # otherwise primitive
        if val is None or isinstance(val, (bool, int, float, str)):
            return val
        raise ValueError("Invalid value in node")

    # Second pass: fill placeholders
    for nid, node in nodes.items():
        t = node["t"]
        v = node["v"]
        if t == "list":
            if not isinstance(v, list):
                raise ValueError("List node 'v' must be a list")
            lst = placeholders[nid]
            for item in v:
                lst.append(resolve(item))
        else:  # dict
            if not isinstance(v, dict):
                raise ValueError("Dict node 'v' must be an object")
            dct = placeholders[nid]
            for k, val in v.items():
                if not isinstance(k, str):
                    raise ValueError("Dict keys must be strings")
                dct[k] = resolve(val)

    # Resolve root
    if isinstance(root, dict) and set(root.keys()) == {"$ref"}:
        ref = root["$ref"]
        if not isinstance(ref, str) or ref not in placeholders:
            raise ValueError("Invalid root $ref")
        return placeholders[ref]
    # Root can be a primitive
    if root is None or isinstance(root, (bool, int, float, str)):
        return root
    raise ValueError("Invalid root value")

import re
from typing import Optional

# Token types
NUMBER = 'NUMBER'
PLUS = 'PLUS'
MINUS = 'MINUS'
MUL = 'MUL'
DIV = 'DIV'
MOD = 'MOD'
POW = 'POW'
LPAREN = 'LPAREN'
RPAREN = 'RPAREN'
EOF = 'EOF'

class Token:
    def __init__(self, type_, value: Optional[float] = None):
        self.type = type_
        self.value = value
    def __repr__(self):
        return f"Token({self.type}, {self.value})"

def tokenize(s: str):
    i = 0
    n = len(s)
    tokens = []
    number_re = re.compile(r"\d+(?:\.\d+)?")
    while i < n:
        ch = s[i]
        if ch.isspace():
            i += 1
            continue
        if ch.isdigit():
            m = number_re.match(s, i)
            if not m:
                raise ValueError('Invalid number')
            num = float(m.group(0))
            tokens.append(Token(NUMBER, num))
            i = m.end()
            continue
        # two-char operator **
        if ch == '*':
            if i + 1 < n and s[i+1] == '*':
                tokens.append(Token(POW))
                i += 2
            else:
                tokens.append(Token(MUL))
                i += 1
            continue
        if ch == '+':
            tokens.append(Token(PLUS))
            i += 1
            continue
        if ch == '-':
            tokens.append(Token(MINUS))
            i += 1
            continue
        if ch == '/':
            tokens.append(Token(DIV))
            i += 1
            continue
        if ch == '%':
            tokens.append(Token(MOD))
            i += 1
            continue
        if ch == '(':
            tokens.append(Token(LPAREN))
            i += 1
            continue
        if ch == ')':
            tokens.append(Token(RPAREN))
            i += 1
            continue
        # anything else invalid
        raise ValueError(f'Invalid token: {ch}')
    tokens.append(Token(EOF))
    return tokens

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0
        self.current = tokens[0]

    def eat(self, type_):
        if self.current.type == type_:
            self.pos += 1
            self.current = self.tokens[self.pos]
        else:
            raise ValueError('Unexpected token')

    def parse(self):
        if self.current.type == EOF:
            raise ValueError('Empty expression')
        result = self.expr()
        if self.current.type != EOF:
            raise ValueError('Unexpected token')
        return result

    # expression -> add_sub
    def expr(self):
        return self.add_sub()

    # add_sub -> mul_div ( (PLUS|MINUS) mul_div )*
    def add_sub(self):
        result = self.mul_div()
        while self.current.type in (PLUS, MINUS):
            tok = self.current.type
            self.eat(tok)
            rhs = self.mul_div()
            if tok == PLUS:
                result = result + rhs
            else:
                result = result - rhs
        return result

    # mul_div -> unary ( (MUL|DIV|MOD) unary )*
    def mul_div(self):
        result = self.unary()
        while self.current.type in (MUL, DIV, MOD):
            tok = self.current.type
            self.eat(tok)
            rhs = self.unary()
            if tok == MUL:
                result = result * rhs
            elif tok == DIV:
                if rhs == 0:
                    raise ValueError('Division by zero')
                result = result / rhs
            else:  # MOD
                if rhs == 0:
                    raise ValueError('Modulo by zero')
                result = result % rhs
        return result

    # unary -> (PLUS|MINUS) unary | power
    def unary(self):
        if self.current.type == PLUS:
            self.eat(PLUS)
            return +self.unary()
        if self.current.type == MINUS:
            self.eat(MINUS)
            return -self.unary()
        return self.power()

    # power -> primary (POW power)?   right-associative
    def power(self):
        left = self.primary()
        if self.current.type == POW:
            self.eat(POW)
            right = self.power()
            # pow handles negative exponents and floats
            return left ** right
        return left

    # primary -> NUMBER | LPAREN expr RPAREN
    def primary(self):
        if self.current.type == NUMBER:
            val = self.current.value
            self.eat(NUMBER)
            return val
        if self.current.type == LPAREN:
            self.eat(LPAREN)
            val = self.expr()
            if self.current.type != RPAREN:
                raise ValueError('Unbalanced parentheses')
            self.eat(RPAREN)
            return val
        raise ValueError('Unexpected token in primary')


def evaluate(expr: str) -> float:
    tokens = tokenize(expr)
    p = Parser(tokens)
    result = p.parse()
    return float(result)

import re

class ParseError(ValueError):
    pass

_token_spec = [
    ('NUMBER', r"\d+"),
    ('NAME', r"[A-Za-z_][A-Za-z0-9_]*"),
    ('OP', r"==|!=|<=|>=|[+\-*/%<>]") ,
    ('LPAREN', r"\("),
    ('RPAREN', r"\)"),
    ('SKIP', r"[ \t]+"),
    ('MISMATCH', r".")
]
_token_re = re.compile('|'.join('(?P<%s>%s)' % pair for pair in _token_spec))

class Token:
    def __init__(self, typ, val):
        self.type = typ
        self.val = val
    def __repr__(self):
        return f"Token({self.type},{self.val})"

def tokenize(expr):
    tokens = []
    pos = 0
    while pos < len(expr):
        m = _token_re.match(expr, pos)
        if not m:
            raise ParseError('Unexpected token')
        typ = m.lastgroup
        val = m.group(typ)
        if typ == 'NUMBER':
            tokens.append(Token('NUMBER', int(val)))
        elif typ == 'NAME':
            tokens.append(Token('NAME', val))
        elif typ == 'OP':
            tokens.append(Token('OP', val))
        elif typ == 'LPAREN':
            tokens.append(Token('LPAREN', val))
        elif typ == 'RPAREN':
            tokens.append(Token('RPAREN', val))
        elif typ == 'SKIP':
            pass
        else:
            raise ParseError('Unexpected token')
        pos = m.end()
    tokens.append(Token('EOF', None))
    return tokens

class ExprParser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0
    def peek(self):
        return self.tokens[self.pos]
    def next(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok
    def accept_op(self, ops):
        tok = self.peek()
        if tok.type == 'OP' and tok.val in ops:
            self.pos += 1
            return tok.val
        return None
    def expect(self, typ):
        tok = self.peek()
        if tok.type == typ:
            self.pos += 1
            return tok
        raise ParseError('Expected %s' % typ)
    def parse(self):
        node = self.parse_comparison()
        if self.peek().type != 'EOF':
            raise ParseError('Unexpected token')
        return node
    def parse_comparison(self):
        node = self.parse_add()
        while True:
            op = self.accept_op(['==','!=','<','<=','>','>='])
            if not op:
                break
            right = self.parse_add()
            node = ('binop', op, node, right)
        return node
    def parse_add(self):
        node = self.parse_mul()
        while True:
            op = self.accept_op(['+','-'])
            if not op:
                break
            right = self.parse_mul()
            node = ('binop', op, node, right)
        return node
    def parse_mul(self):
        node = self.parse_primary()
        while True:
            op = self.accept_op(['*','/','%'])
            if not op:
                break
            right = self.parse_primary()
            node = ('binop', op, node, right)
        return node
    def parse_primary(self):
        tok = self.peek()
        if tok.type == 'NUMBER':
            self.next()
            return ('num', tok.val)
        if tok.type == 'NAME':
            self.next()
            return ('var', tok.val)
        if tok.type == 'LPAREN':
            self.next()
            node = self.parse_comparison()
            if self.peek().type != 'RPAREN':
                raise ParseError('Unbalanced parentheses')
            self.next()
            return node
        raise ParseError('Unexpected token in expression')

def parse_expression(s):
    try:
        tokens = tokenize(s)
        p = ExprParser(tokens)
        node = p.parse()
        return node
    except ParseError as e:
        raise ValueError('Syntax error')

def eval_expr(node, env):
    t = node[0]
    if t == 'num':
        return node[1]
    if t == 'var':
        name = node[1]
        if name not in env:
            raise ValueError('Undefined variable')
        return env[name]
    if t == 'binop':
        op = node[1]
        lnode = node[2]
        rnode = node[3]
        left = eval_expr(lnode, env)
        right = eval_expr(rnode, env)
        if op == '+':
            return left + right
        if op == '-':
            return left - right
        if op == '*':
            return left * right
        if op == '/':
            if right == 0:
                raise ValueError('Division by zero')
            return left // right
        if op == '%':
            if right == 0:
                raise ValueError('Division by zero')
            return left % right
        if op == '==':
            return 1 if left == right else 0
        if op == '!=':
            return 1 if left != right else 0
        if op == '<':
            return 1 if left < right else 0
        if op == '<=':
            return 1 if left <= right else 0
        if op == '>':
            return 1 if left > right else 0
        if op == '>=':
            return 1 if left >= right else 0
    raise ValueError('Invalid expression')

_name_re = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')

def split_lines(src):
    return src.splitlines()

def parse_block(lines, start, top=False):
    stmts = []
    i = start
    n = len(lines)
    while i < n:
        raw = lines[i]
        line = raw.strip()
        i += 1
        if line == '' or line.startswith('#'):
            continue
        if line == '}':
            if top:
                # stray closing brace at top level is a syntax error
                raise ValueError('Syntax error')
            return stmts, i, ''
        if line.startswith('}'):
            # stray text after }
            rem = line[1:].strip()
            if top:
                raise ValueError('Syntax error')
            return stmts, i, rem
        if line.startswith('if '):
            if not line.endswith('{'):
                raise ValueError('Syntax error')
            cond_str = line[3:-1].strip()
            if cond_str == '':
                raise ValueError('Syntax error')
            cond_expr = parse_expression(cond_str)
            then_stmts, next_i, trailing = parse_block(lines, i)
            i = next_i
            else_stmts = None
            if trailing and trailing.startswith('else'):
                rest = trailing[4:].strip()
                if not rest.startswith('{'):
                    raise ValueError('Syntax error')
                # parse else block
                else_stmts, i2, trailing2 = parse_block(lines, i)
                i = i2
            else:
                # look ahead
                j = i
                while j < n and lines[j].strip() == '':
                    j += 1
                if j < n and lines[j].strip().startswith('else'):
                    el_line = lines[j].strip()
                    if not el_line.endswith('{'):
                        raise ValueError('Syntax error')
                    j += 1
                    else_stmts, i2, trailing2 = parse_block(lines, j)
                    i = i2
            stmts.append(('if', cond_expr, then_stmts, else_stmts))
            continue
        if line.startswith('while '):
            if not line.endswith('{'):
                raise ValueError('Syntax error')
            cond_str = line[6:-1].strip()
            if cond_str == '':
                raise ValueError('Syntax error')
            cond_expr = parse_expression(cond_str)
            body_stmts, next_i, trailing = parse_block(lines, i)
            if trailing and trailing != '':
                raise ValueError('Syntax error')
            i = next_i
            stmts.append(('while', cond_expr, body_stmts))
            continue
        if line.startswith('print'):
            if not line.startswith('print(') or not line.endswith(')'):
                raise ValueError('Syntax error')
            inner = line[6:-1].strip() if line.startswith('print(') else None
            if inner is None:
                raise ValueError('Syntax error')
            expr = parse_expression(inner)
            stmts.append(('print', expr))
            continue
        # assignment or input
        if '=' in line:
            parts = line.split('=', 1)
            left = parts[0].strip()
            right = parts[1].strip()
            if not _name_re.match(left):
                raise ValueError('Syntax error')
            if right == 'input()':
                stmts.append(('input', left))
                continue
            # else expression
            expr = parse_expression(right)
            stmts.append(('assign', left, expr))
            continue
        raise ValueError('Syntax error')
    # if we reach end without finding closing brace
    if top:
        return stmts, i, ''
    raise ValueError('Unbalanced braces')

def parse_program(src):
    lines = split_lines(src)
    stmts, i, trailing = parse_block(lines, 0, top=True)
    if i != len(lines):
        # extra content after top-level parsing
        # allow trailing blank lines
        for j in range(i, len(lines)):
            if lines[j].strip() != '':
                raise ValueError('Syntax error')
    return stmts

def exec_block(stmts, env, inputs, out):
    i = 0
    while i < len(stmts):
        st = stmts[i]
        kind = st[0]
        if kind == 'print':
            val = eval_expr(st[1], env)
            out.append(str(val) + '\n')
            i += 1
        elif kind == 'assign':
            name = st[1]
            val = eval_expr(st[2], env)
            env[name] = val
            i += 1
        elif kind == 'input':
            name = st[1]
            if not inputs:
                raise ValueError('No input')
            env[name] = inputs.pop(0)
            i += 1
        elif kind == 'if':
            cond = eval_expr(st[1], env)
            if cond != 0:
                exec_block(st[2], env, inputs, out)
            else:
                if st[3] is not None:
                    exec_block(st[3], env, inputs, out)
            i += 1
        elif kind == 'while':
            cond_expr = st[1]
            body = st[2]
            while True:
                cond = eval_expr(cond_expr, env)
                if cond == 0:
                    break
                exec_block(body, env, inputs, out)
            i += 1
        else:
            raise ValueError('Unknown statement')

def run_program(src, inputs=None):
    if inputs is None:
        inputs = []
    else:
        inputs = list(inputs)
    stmts = parse_program(src)
    env = {}
    out = []
    exec_block(stmts, env, inputs, out)
    return ''.join(out)

import threading


class Bank:
    def __init__(self):
        self._balances = {}
        self._lock = threading.Lock()

    def create_account(self, acc_id: str) -> None:
        with self._lock:
            if acc_id in self._balances:
                raise ValueError("account already exists")
            self._balances[acc_id] = 0.0

    def deposit(self, acc_id: str, amount: float) -> None:
        if amount <= 0:
            raise ValueError("amount must be > 0")
        with self._lock:
            if acc_id not in self._balances:
                raise ValueError("account does not exist")
            self._balances[acc_id] += float(amount)

    def withdraw(self, acc_id: str, amount: float) -> None:
        if amount <= 0:
            raise ValueError("amount must be > 0")
        with self._lock:
            if acc_id not in self._balances:
                raise ValueError("account does not exist")
            if self._balances[acc_id] < amount:
                raise ValueError("insufficient funds")
            self._balances[acc_id] -= float(amount)

    def transfer(self, from_id: str, to_id: str, amount: float) -> None:
        if amount <= 0:
            raise ValueError("amount must be > 0")
        with self._lock:
            if from_id not in self._balances or to_id not in self._balances:
                raise ValueError("account does not exist")
            if self._balances[from_id] < amount:
                raise ValueError("insufficient funds")
            # perform transfer atomically
            self._balances[from_id] -= float(amount)
            self._balances[to_id] += float(amount)

    def balance(self, acc_id: str) -> float:
        with self._lock:
            if acc_id not in self._balances:
                raise ValueError("account does not exist")
            return float(self._balances[acc_id])

def bencode(obj: object) -> bytes:
    """Encode a Python object to bencode bytes.

    Supported types: int (but not bool), bytes, str (UTF-8), list, dict (keys must be str).
    """
    def enc(o):
        # Reject booleans explicitly (they are instances of int)
        if isinstance(o, bool):
            raise ValueError("bool is not supported")
        if isinstance(o, int):
            # integer encoding
            return b'i' + str(o).encode('ascii') + b'e'
        if isinstance(o, bytes):
            return str(len(o)).encode('ascii') + b':' + o
        if isinstance(o, str):
            b = o.encode('utf-8')
            return str(len(b)).encode('ascii') + b':' + b
        if isinstance(o, list):
            parts = [b'l']
            for item in o:
                parts.append(enc(item))
            parts.append(b'e')
            return b''.join(parts)
        if isinstance(o, dict):
            # keys must be str
            # convert keys to UTF-8 bytes and sort by raw bytes
            items = []
            for k, v in o.items():
                if not isinstance(k, str):
                    raise ValueError('dict keys must be str')
                kb = k.encode('utf-8')
                items.append((kb, v))
            # sort by raw bytes of key
            items.sort(key=lambda kv: kv[0])
            parts = [b'd']
            for kb, v in items:
                parts.append(str(len(kb)).encode('ascii') + b':' + kb)
                parts.append(enc(v))
            parts.append(b'e')
            return b''.join(parts)
        raise ValueError(f'Unsupported type: {type(o)!r}')

    return enc(obj)


def bdecode(data: bytes) -> object:
    """Decode bencoded bytes to Python objects.

    Returns int, bytes, list, dict (dict keys are bytes).
    """
    if isinstance(data, bytearray):
        data = bytes(data)
    if not isinstance(data, (bytes,)):
        raise ValueError('data must be bytes')
    n = len(data)
    if n == 0:
        raise ValueError('empty input')

    def parse_int(i):
        # data[i] == ord('i')
        j = data.find(b'e', i+1)
        if j == -1:
            raise ValueError('unterminated integer')
        num_bytes = data[i+1:j]
        if len(num_bytes) == 0:
            raise ValueError('empty integer')
        # negative?
        if num_bytes == b'-':
            raise ValueError('bare - is not valid integer')
        if num_bytes[0:1] == b'-':
            if num_bytes == b'-0':
                raise ValueError("-0 is not allowed")
            # ok otherwise
        else:
            # positive: prohibit leading zeros unless exactly '0'
            if len(num_bytes) > 1 and num_bytes[0:1] == b'0':
                raise ValueError('leading zero in integer')
        try:
            val = int(num_bytes.decode('ascii'))
        except Exception:
            raise ValueError('invalid integer')
        return val, j+1

    def parse_bytes(i):
        # parse length prefix until ':'
        j = i
        if j >= n or not (48 <= data[j] <= 57):  # not digit
            raise ValueError('invalid string length')
        # gather digits
        while j < n and 48 <= data[j] <= 57:
            j += 1
        if j >= n or data[j] != ord(':'):
            raise ValueError('missing colon in string')
        len_bytes = data[i:j]
        if len(len_bytes) > 1 and len_bytes[0:1] == b'0':
            raise ValueError('leading zero in string length')
        try:
            length = int(len_bytes.decode('ascii'))
        except Exception:
            raise ValueError('invalid string length')
        start = j+1
        end = start + length
        if end > n:
            raise ValueError('string length exceeds data')
        return data[start:end], end

    def parse_value(i):
        if i >= n:
            raise ValueError('unexpected end')
        c = data[i:i+1]
        if c == b'i':
            return parse_int(i)
        if c == b'l':
            lst = []
            idx = i+1
            while True:
                if idx >= n:
                    raise ValueError('unterminated list')
                if data[idx:idx+1] == b'e':
                    return lst, idx+1
                val, idx = parse_value(idx)
                lst.append(val)
        if c == b'd':
            d = {}
            idx = i+1
            while True:
                if idx >= n:
                    raise ValueError('unterminated dict')
                if data[idx:idx+1] == b'e':
                    return d, idx+1
                key, idx = parse_value(idx)
                # keys must be bytes
                if not isinstance(key, (bytes, bytearray)):
                    raise ValueError('dict keys must be bytes')
                # ensure key is bytes (convert bytearray)
                if isinstance(key, bytearray):
                    key = bytes(key)
                val, idx = parse_value(idx)
                d[key] = val
            # unreachable
        # otherwise it's a byte string (length-prefixed)
        return parse_bytes(i)

    val, idx = parse_value(0)
    if idx != n:
        raise ValueError('trailing data')
    return val

import re
from typing import List, Tuple, Optional


def run_asm(src: str) -> str:
    # Parse and assemble
    lines = src.splitlines()
    instrs: List[Tuple[str, Optional[object]]] = []  # (mnemonic, arg)
    labels = {}
    label_re = re.compile(r'^[A-Za-z0-9_]+$')

    for raw in lines:
        # remove comments
        line = raw
        if '#' in line:
            line = line[: line.index('#')]
        line = line.strip()
        if not line:
            continue
        # label line
        if line.endswith(':'):
            name = line[:-1].strip()
            if not name or not label_re.match(name):
                raise ValueError(f'invalid label: {name}')
            if name in labels:
                raise ValueError('duplicate label')
            labels[name] = len(instrs)
            continue
        parts = line.split()
        if not parts:
            continue
        op = parts[0].upper()
        args = parts[1:]
        # validate operand counts
        if op == 'PUSH':
            if len(args) != 1:
                raise ValueError('wrong operand count')
            try:
                val = int(args[0])
            except Exception:
                raise ValueError('non-integer PUSH')
            instrs.append((op, val))
        elif op in ('JMP', 'JZ', 'JNZ'):
            if len(args) != 1:
                raise ValueError('wrong operand count')
            name = args[0]
            if not label_re.match(name):
                raise ValueError('invalid label')
            instrs.append((op, name))
        elif op in ('POP', 'DUP', 'SWAP', 'ADD', 'SUB', 'MUL', 'DIV', 'NEG', 'PRINT', 'HALT'):
            if len(args) != 0:
                raise ValueError('wrong operand count')
            instrs.append((op, None))
        else:
            raise ValueError('unknown mnemonic')

    # resolve labels for jumps
    resolved: List[Tuple[str, Optional[object]]] = []
    for op, arg in instrs:
        if op in ('JMP', 'JZ', 'JNZ'):
            name = arg
            if name not in labels:
                raise ValueError('undefined label')
            resolved.append((op, labels[name]))
        else:
            resolved.append((op, arg))

    # execute
    stack: List[int] = []
    out_lines: List[str] = []
    ip = 0
    n = len(resolved)
    while ip < n:
        op, arg = resolved[ip]
        if op == 'PUSH':
            stack.append(arg)  # type: ignore
            ip += 1
        elif op == 'POP':
            if not stack:
                raise ValueError('stack underflow')
            stack.pop()
            ip += 1
        elif op == 'DUP':
            if not stack:
                raise ValueError('stack underflow')
            stack.append(stack[-1])
            ip += 1
        elif op == 'SWAP':
            if len(stack) < 2:
                raise ValueError('stack underflow')
            a = stack.pop()
            b = stack.pop()
            stack.append(a)
            stack.append(b)
            ip += 1
        elif op == 'ADD':
            if len(stack) < 2:
                raise ValueError('stack underflow')
            a = stack.pop()
            b = stack.pop()
            stack.append(b + a)
            ip += 1
        elif op == 'SUB':
            if len(stack) < 2:
                raise ValueError('stack underflow')
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)
            ip += 1
        elif op == 'MUL':
            if len(stack) < 2:
                raise ValueError('stack underflow')
            a = stack.pop()
            b = stack.pop()
            stack.append(b * a)
            ip += 1
        elif op == 'DIV':
            if len(stack) < 2:
                raise ValueError('stack underflow')
            a = stack.pop()
            b = stack.pop()
            if a == 0:
                raise ValueError('division by zero')
            # integer division truncated toward zero
            stack.append(int(b / a))
            ip += 1
        elif op == 'NEG':
            if not stack:
                raise ValueError('stack underflow')
            stack[-1] = -stack[-1]
            ip += 1
        elif op == 'PRINT':
            if not stack:
                raise ValueError('stack underflow')
            v = stack.pop()
            out_lines.append(str(v) + '\n')
            ip += 1
        elif op == 'HALT':
            break
        elif op == 'JMP':
            ip = arg  # type: ignore
        elif op == 'JZ':
            if not stack:
                raise ValueError('stack underflow')
            v = stack.pop()
            if v == 0:
                ip = arg  # type: ignore
            else:
                ip += 1
        elif op == 'JNZ':
            if not stack:
                raise ValueError('stack underflow')
            v = stack.pop()
            if v != 0:
                ip = arg  # type: ignore
            else:
                ip += 1
        else:
            raise ValueError('unknown mnemonic')

    return ''.join(out_lines)

from typing import List


def process_csv(text: str) -> str:
    if text is None or text == "":
        raise ValueError("empty input")

    i = 0
    n = len(text)
    rows: List[List[str]] = []
    current_row: List[str] = []
    current_field_chars: List[str] = []
    in_quotes = False

    while i < n:
        c = text[i]
        if in_quotes:
            if c == '"':
                # either escaped quote or closing quote
                if i + 1 < n and text[i + 1] == '"':
                    current_field_chars.append('"')
                    i += 2
                else:
                    # closing quote
                    i += 1
                    in_quotes = False
                    # after closing quote, next char must be comma, newline, or EOF
                    if i < n and text[i] not in (',', '\n'):
                        raise ValueError("invalid character after closing quote")
                continue
            else:
                current_field_chars.append(c)
                i += 1
                continue
        else:
            if c == '"':
                # start quoted field
                # if field already has characters, it's an error in strict mode
                if current_field_chars:
                    # treat it as normal char (be permissive), but spec is strict; raise
                    raise ValueError("unexpected quote in unquoted field")
                in_quotes = True
                i += 1
                continue
            elif c == ',':
                current_row.append(''.join(current_field_chars))
                current_field_chars = []
                i += 1
                continue
            elif c == '\n':
                current_row.append(''.join(current_field_chars))
                current_field_chars = []
                rows.append(current_row)
                current_row = []
                i += 1
                continue
            else:
                current_field_chars.append(c)
                i += 1
                continue

    # end while
    if in_quotes:
        raise ValueError("unterminated quoted field")

    # if there is remaining data (either fields collected or partial row), append final field/row
    if current_field_chars or current_row:
        current_row.append(''.join(current_field_chars))
        rows.append(current_row)

    if not rows:
        raise ValueError("empty input")

    # header
    header = rows[0]
    ncols = len(header)
    for r in rows[1:]:
        if len(r) != ncols:
            raise ValueError("row has different column count")

    # transform: filter status == 'skip'
    status_idx = None
    sort_idx = None
    for idx, name in enumerate(header):
        if name == 'status':
            status_idx = idx
        if name == 'sort':
            sort_idx = idx

    data_rows = rows[1:]
    if status_idx is not None:
        filtered = [r for r in data_rows if r[status_idx] != 'skip']
    else:
        filtered = list(data_rows)

    # sorting
    if sort_idx is not None:
        def sort_key(row):
            val = row[sort_idx]
            try:
                num = float(val)
                return (0, num)
            except Exception:
                return (1, val)

        # stable sort
        filtered = sorted(filtered, key=sort_key)

    # serialization
    def serialize_field(f: str) -> str:
        need_quote = (',' in f) or ('"' in f) or ('\n' in f)
        if '"' in f:
            f_escaped = f.replace('"', '""')
        else:
            f_escaped = f
        if need_quote:
            return '"' + f_escaped + '"'
        else:
            return f_escaped

    out_lines: List[str] = []
    out_lines.append(','.join(serialize_field(x) for x in header))
    for r in filtered:
        out_lines.append(','.join(serialize_field(x) for x in r))

    return '\n'.join(out_lines) + '\n'

import json
from typing import Any, Dict, List


def encode(obj: object) -> str:
    # Assign a unique index to each Python object by its id()
    # Build node entries describing type and references by index
    seen = {}  # id(obj) -> index
    nodes = []

    def add(o):
        oid = id(o)
        if oid in seen:
            return seen[oid]
        idx = len(nodes)
        seen[oid] = idx
        # placeholder to reserve index
        nodes.append(None)

        # Determine type and representation
        if o is None:
            nodes[idx] = {"t": "none"}
        elif isinstance(o, bool):
            # bool is a subclass of int, check before int
            nodes[idx] = {"t": "bool", "v": o}
        elif isinstance(o, int):
            nodes[idx] = {"t": "int", "v": o}
        elif isinstance(o, float):
            nodes[idx] = {"t": "float", "v": o}
        elif isinstance(o, str):
            nodes[idx] = {"t": "str", "v": o}
        elif isinstance(o, list):
            # recursively add children
            children = []
            for item in o:
                children.append(add(item))
            nodes[idx] = {"t": "list", "v": children}
        elif isinstance(o, dict):
            # only allow string keys
            mapping = {}
            for k, v in o.items():
                if not isinstance(k, str):
                    raise ValueError("Only string dict keys are supported")
                mapping[k] = add(v)
            nodes[idx] = {"t": "dict", "v": mapping}
        else:
            raise ValueError(f"Unsupported type: {type(o)!r}")
        return idx

    root_idx = add(obj)
    out = {"root": root_idx, "nodes": nodes}
    try:
        return json.dumps(out, separators=(",", ":"), ensure_ascii=False)
    except (TypeError, ValueError):
        # propagate as ValueError
        raise


def decode(s: str) -> object:
    try:
        data = json.loads(s)
    except Exception as e:
        raise ValueError("Malformed input: not valid JSON") from e

    if not isinstance(data, dict):
        raise ValueError("Malformed input: top-level must be an object")
    if "root" not in data or "nodes" not in data:
        raise ValueError("Malformed input: missing root or nodes")
    root = data["root"]
    nodes = data["nodes"]
    if not isinstance(root, int):
        raise ValueError("Malformed input: root must be int")
    if not isinstance(nodes, list):
        raise ValueError("Malformed input: nodes must be list")

    # First pass: create placeholders or primitive values
    n = len(nodes)
    if not (0 <= root < n):
        raise ValueError("Malformed input: root index out of range")

    objects: List[Any] = [None] * n

    for i, node in enumerate(nodes):
        if not isinstance(node, dict):
            raise ValueError("Malformed input: each node must be object")
        if "t" not in node:
            raise ValueError("Malformed input: node missing type")
        t = node["t"]
        if t == "none":
            objects[i] = None
        elif t == "bool":
            if "v" not in node or not isinstance(node["v"], bool):
                raise ValueError("Malformed input: invalid bool node")
            objects[i] = node["v"]
        elif t == "int":
            if "v" not in node or not isinstance(node["v"], int):
                # JSON may parse numbers as int or float; require int
                raise ValueError("Malformed input: invalid int node")
            objects[i] = node["v"]
        elif t == "float":
            if "v" not in node or not (isinstance(node["v"], float) or isinstance(node["v"], int)):
                # JSON may give ints for floats; accept int too and convert
                raise ValueError("Malformed input: invalid float node")
            objects[i] = float(node["v"])
        elif t == "str":
            if "v" not in node or not isinstance(node["v"], str):
                raise ValueError("Malformed input: invalid str node")
            objects[i] = node["v"]
        elif t == "list":
            if "v" not in node or not isinstance(node["v"], list):
                raise ValueError("Malformed input: invalid list node")
            # placeholder list to be filled later
            objects[i] = []
        elif t == "dict":
            if "v" not in node or not isinstance(node["v"], dict):
                raise ValueError("Malformed input: invalid dict node")
            # keys must be strings and values indices
            objects[i] = {}
        else:
            raise ValueError("Malformed input: unknown node type")

    # Second pass: fill containers
    for i, node in enumerate(nodes):
        t = node["t"]
        if t == "list":
            children = node["v"]
            lst = objects[i]
            for idx in children:
                if not isinstance(idx, int) or not (0 <= idx < n):
                    raise ValueError("Malformed input: invalid child index")
                lst.append(objects[idx])
        elif t == "dict":
            mapping = node["v"]
            d = objects[i]
            for k, idx in mapping.items():
                if not isinstance(k, str):
                    raise ValueError("Malformed input: dict keys must be strings")
                if not isinstance(idx, int) or not (0 <= idx < n):
                    raise ValueError("Malformed input: invalid dict child index")
                d[k] = objects[idx]

    return objects[root]

from typing import List, Tuple, Union


class Token:
    def __init__(self, type_: str, value=None):
        self.type = type_
        self.value = value

    def __repr__(self):
        return f"Token({self.type!r}, {self.value!r})"


def tokenize(s: str) -> List[Token]:
    i = 0
    n = len(s)
    tokens: List[Token] = []
    while i < n:
        ch = s[i]
        if ch.isspace():
            i += 1
            continue
        if ch.isdigit():
            j = i
            while j < n and s[j].isdigit():
                j += 1
            if j < n and s[j] == '.':
                j += 1
                # must have digits after the decimal
                if j >= n or not s[j].isdigit():
                    raise ValueError('Invalid number')
                while j < n and s[j].isdigit():
                    j += 1
            num_str = s[i:j]
            try:
                val = float(num_str)
            except Exception:
                raise ValueError('Invalid number')
            tokens.append(Token('NUMBER', val))
            i = j
            continue
        # operators and parentheses
        if ch in '+-*/%()':
            # handle '**'
            if ch == '*':
                if i + 1 < n and s[i + 1] == '*':
                    tokens.append(Token('OP', '**'))
                    i += 2
                    continue
                else:
                    tokens.append(Token('OP', '*'))
                    i += 1
                    continue
            elif ch in '+-/%':
                tokens.append(Token('OP', ch))
                i += 1
                continue
            elif ch == '/':
                tokens.append(Token('OP', '/'))
                i += 1
                continue
            elif ch == '(' or ch == ')':
                tokens.append(Token(ch))
                i += 1
                continue
        # any other char invalid
        raise ValueError('Invalid token')
    return tokens

def evaluate(expr: str) -> float:
    # tokenize
    tokens = tokenize(expr)
    if not tokens:
        raise ValueError('Empty expression')
    pos = 0

    def peek() -> Union[Token, None]:
        return tokens[pos] if pos < len(tokens) else None

    def consume(expected_type=None, expected_value=None) -> Token:
        nonlocal pos
        if pos >= len(tokens):
            raise ValueError('Unexpected end of expression')
        tok = tokens[pos]
        if expected_type is not None and tok.type != expected_type:
            raise ValueError('Unexpected token')
        if expected_value is not None and tok.value != expected_value:
            raise ValueError('Unexpected token')
        pos += 1
        return tok

    def parse_primary() -> float:
        tok = peek()
        if tok is None:
            raise ValueError('Unexpected end of expression')
        if tok.type == 'NUMBER':
            consume('NUMBER')
            return float(tok.value)
        if tok.type == '(':
            consume('(')
            val = parse_add()
            if peek() is None or peek().type != ')':
                raise ValueError('Unbalanced parentheses')
            consume(')')
            return val
        raise ValueError('Unexpected token')

    def parse_power() -> float:
        # primary ('**' parse_unary)? with right-assoc
        left = parse_primary()
        if peek() is not None and peek().type == 'OP' and peek().value == '**':
            consume('OP', '**')
            right = parse_unary()
            try:
                return left ** right
            except ZeroDivisionError:
                # propagate as ValueError
                raise ValueError('Math error')
        return left

    def parse_unary() -> float:
        tok = peek()
        if tok is not None and tok.type == 'OP' and tok.value in ('+', '-'):
            op = tok.value
            consume('OP', op)
            val = parse_unary()
            return val if op == '+' else -val
        return parse_power()

    def parse_mul() -> float:
        val = parse_unary()
        while True:
            tok = peek()
            if tok is not None and tok.type == 'OP' and tok.value in ('*', '/', '%'):
                op = tok.value
                consume('OP', op)
                rhs = parse_unary()
                if op == '*':
