from typing import List, Tuple, Optional


class ParseError(Exception):
    pass


def run_program(src: str, inputs: list | None = None) -> str:
    try:
        parser = Parser(src)
        prog = parser.parse_program()
        executor = Executor(prog, inputs or [])
        return executor.execute()
    except ValueError:
        raise
    except Exception as e:
        # convert any internal parse/execution errors to ValueError as required
        raise ValueError from e


# Parser and AST

class Parser:
    def __init__(self, src: str):
        self.lines = src.splitlines()
        self.n = len(self.lines)

    def parse_program(self):
        stmts, next_i = self._parse_block(0, allow_end=True)
        if next_i != self.n:
            # stray closing brace or extra lines
            # if remaining lines are blank, ok
            for i in range(next_i, self.n):
                if self.lines[i].strip() != '':
                    raise ParseError('trailing')
        return stmts

    def _parse_block(self, i: int, allow_end: bool = False) -> Tuple[List, int]:
        stmts = []
        while i < self.n:
            line = self.lines[i].strip()
            if line == '':
                i += 1
                continue
            if line == '}':
                return stmts, i + 1
            # if this line ends with '{' it's a block opener
            if line.startswith('if ' ) and line.endswith('{'):
                cond_s = line[3:-1].strip()
                cond = cond_s
                # parse inner block
                inner, ni = self._parse_block(i + 1)
                # check for else
                else_block = None
                if ni < self.n:
                    nextline = self.lines[ni].strip()
                    if nextline == 'else {':
                        else_block, ni2 = self._parse_block(ni + 1)
                        ni = ni2
                stmts.append(('if', cond, inner, else_block))
                i = ni
                continue
            if line.startswith('while ') and line.endswith('{'):
                cond_s = line[6:-1].strip()
                inner, ni = self._parse_block(i + 1)
                stmts.append(('while', cond_s, inner))
                i = ni
                continue
            # assignment or print
            if line.startswith('print(') and line.endswith(')'):
                expr = line[len('print('):-1].strip()
                if expr == '':
                    raise ParseError('empty print')
                stmts.append(('print', expr))
                i += 1
                continue
            # assignment
            if '=' in line:
                parts = line.split('=')
                if len(parts) < 2:
                    raise ParseError('bad assign')
                lhs = parts[0].strip()
                rhs = '='.join(parts[1:]).strip()
                if lhs == '' or not lhs.isidentifier():
                    raise ParseError('bad lhs')
                if rhs == 'input()':
                    stmts.append(('input', lhs))
                else:
                    stmts.append(('assign', lhs, rhs))
                i += 1
                continue
            # stray closing brace
            if line == '}':
                return stmts, i + 1
            # unknown
            raise ParseError('syntax')
        if not allow_end:
            # if we were parsing a block but hit EOF without closing
            # But top-level parse allows EOF
            return stmts, self.n
        return stmts, self.n


# Simple expression evaluator using shunting-yard to RPN

class ExprEval:
    def __init__(self, expr: str):
        self.expr = expr
        self.tokens = self.tokenize(expr)
        if not self.tokens:
            raise ParseError('empty expr')
        self.rpn = self.to_rpn(self.tokens)

    def tokenize(self, s: str):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c.isspace():
                i += 1
                continue
            if c.isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(('num', int(s[i:j])))
                i = j
                continue
            if c.isalpha() or c == '_':
                j = i
                while j < n and (s[j].isalnum() or s[j] == '_'):
                    j += 1
                tokens.append(('name', s[i:j]))
                i = j
                continue
            # multi-char operators
            if s.startswith('==', i) or s.startswith('!=', i) or s.startswith('<=', i) or s.startswith('>=', i):
                tokens.append(('op', s[i:i+2]))
                i += 2
                continue
            if c in '+-*/%()<>' :
                tokens.append(('op', c))
                i += 1
                continue
            raise ParseError('bad char')
        return tokens

    def to_rpn(self, tokens):
        prec = {
            '==': 1, '!=': 1, '<': 1, '<=': 1, '>': 1, '>=': 1,
            '+': 2, '-': 2,
            '*': 3, '/': 3, '%': 3,
        }
        output = []
        stack = []
        for ttype, val in tokens:
            if ttype == 'num' or ttype == 'name':
                output.append((ttype, val))
            else:
                # operator or paren
                if val == '(':
                    stack.append(val)
                elif val == ')':
                    while stack and stack[-1] != '(':
                        output.append(('op', stack.pop()))
                    if not stack or stack[-1] != '(':
                        raise ParseError('mismatched paren')
                    stack.pop()
                else:
                    # operator
                    while stack and stack[-1] != '(' and prec.get(stack[-1], 0) >= prec.get(val, 0):
                        output.append(('op', stack.pop()))
                    stack.append(val)
        while stack:
            v = stack.pop()
            if v in '()':
                raise ParseError('mismatched paren')
            output.append(('op', v))
        return output

    def eval(self, env: dict):
        st = []
        for ttype, val in self.rpn:
            if ttype == 'num':
                st.append(val)
            elif ttype == 'name':
                if val == 'input':
                    # input should be used as input() only
                    raise ParseError('bad input')
                if val not in env:
                    raise ValueError('undef')
                st.append(env[val])
            else:
                if val in ('+', '-', '*', '/', '%', '==', '!=', '<', '<=', '>', '>='):
                    if len(st) < 2:
                        raise ParseError('trailing op')
                    b = st.pop()
                    a = st.pop()
                    if val == '+':
                        st.append(a + b)
                    elif val == '-':
                        st.append(a - b)
                    elif val == '*':
                        st.append(a * b)
                    elif val == '/':
                        if b == 0:
                            raise ValueError('div0')
                        st.append(a // b)
                    elif val == '%':
                        if b == 0:
                            raise ValueError('mod0')
                        st.append(a % b)
                    elif val == '==':
                        st.append(1 if a == b else 0)
                    elif val == '!=':
                        st.append(1 if a != b else 0)
                    elif val == '<':
                        st.append(1 if a < b else 0)
                    elif val == '<=':
                        st.append(1 if a <= b else 0)
                    elif val == '>':
                        st.append(1 if a > b else 0)
                    elif val == '>=':
                        st.append(1 if a >= b else 0)
                else:
                    raise ParseError('bad op')
        if len(st) != 1:
            raise ParseError('bad expr')
        return st[0]


class Executor:
    def __init__(self, stmts, inputs: list):
        self.stmts = stmts
        self.env = {}
        self.inputs = list(inputs)
        self.out_lines = []

    def execute(self):
        self._exec_block(self.stmts)
        return ''.join(line + '\n' for line in self.out_lines)

    def _eval_expr(self, expr: str) -> int:
        ee = ExprEval(expr)
        return ee.eval(self.env)

    def _exec_block(self, stmts):
        i = 0
        while i < len(stmts):
            s = stmts[i]
            typ = s[0]
            if typ == 'print':
                val = self._eval_expr(s[1])
                self.out_lines.append(str(val))
            elif typ == 'assign':
                v = self._eval_expr(s[2])
                self.env[s[1]] = v
            elif typ == 'input':
                if not self.inputs:
                    raise ValueError('no input')
                self.env[s[1]] = self.inputs.pop(0)
            elif typ == 'if':
                cond = self._eval_expr(s[1])
                if cond != 0:
                    self._exec_block(s[2])
                else:
                    if s[3] is not None:
                        self._exec_block(s[3])
            elif typ == 'while':
                while self._eval_expr(s[1]) != 0:
                    self._exec_block(s[2])
            else:
                raise ParseError('bad stmt')
            i += 1

import threading

class Bank:
    def __init__(self):
        # single re-entrant lock protecting the accounts dict
        self._lock = threading.RLock()
        self._accounts = {}  # acc_id -> float balance

    def create_account(self, acc_id: str) -> None:
        with self._lock:
            if acc_id in self._accounts:
                raise ValueError("account already exists")
            self._accounts[acc_id] = 0.0

    def deposit(self, acc_id: str, amount: float) -> None:
        if amount <= 0:
            raise ValueError("deposit amount must be positive")
        with self._lock:
            if acc_id not in self._accounts:
                raise ValueError("account does not exist")
            self._accounts[acc_id] += float(amount)

    def withdraw(self, acc_id: str, amount: float) -> None:
        if amount <= 0:
            raise ValueError("withdraw amount must be positive")
        with self._lock:
            if acc_id not in self._accounts:
                raise ValueError("account does not exist")
            if self._accounts[acc_id] < amount:
                raise ValueError("insufficient funds")
            self._accounts[acc_id] -= float(amount)

    def transfer(self, from_id: str, to_id: str, amount: float) -> None:
        if amount <= 0:
            raise ValueError("transfer amount must be positive")
        with self._lock:
            if from_id not in self._accounts or to_id not in self._accounts:
                raise ValueError("account does not exist")
            if self._accounts[from_id] < amount:
                raise ValueError("insufficient funds")
            # perform transfer atomically
            self._accounts[from_id] -= float(amount)
            self._accounts[to_id] += float(amount)

    def balance(self, acc_id: str) -> float:
        with self._lock:
            if acc_id not in self._accounts:
                raise ValueError("account does not exist")
            return float(self._accounts[acc_id])

def bencode(obj: object) -> bytes:
    """Encode a Python object to bencode bytes.
    Supported types: int, bytes, str, list, dict (with str keys).
    """
    def enc(o):
        # Reject bool explicitly
        if isinstance(o, bool):
            raise ValueError("bool is not supported")
        if isinstance(o, int):
            return b"i" + str(o).encode("ascii") + b"e"
        if isinstance(o, bytes):
            return str(len(o)).encode("ascii") + b":" + o
        if isinstance(o, str):
            bts = o.encode("utf-8")
            return str(len(bts)).encode("ascii") + b":" + bts
        if isinstance(o, list):
            parts = [b"l"]
            for item in o:
                parts.append(enc(item))
            parts.append(b"e")
            return b"".join(parts)
        if isinstance(o, dict):
            # keys must be str
            items = []
            for k, v in o.items():
                if not isinstance(k, str):
                    raise ValueError("dict keys must be str")
                kb = k.encode("utf-8")
                items.append((kb, v))
            # sort by raw key bytes
            items.sort(key=lambda kv: kv[0])
            parts = [b"d"]
            for kb, v in items:
                parts.append(str(len(kb)).encode("ascii") + b":" + kb)
                parts.append(enc(v))
            parts.append(b"e")
            return b"".join(parts)
        raise ValueError(f"Unsupported type: {type(o)!r}")

    return enc(obj)


def bdecode(data: bytes) -> object:
    """Decode bencode bytes to Python object.
    Returns int, bytes, list, dict (with bytes keys).
    """
    if isinstance(data, bytearray):
        data = bytes(data)
    if not isinstance(data, (bytes,)):
        raise ValueError("data must be bytes-like")
    if len(data) == 0:
        raise ValueError("empty input")

    n = len(data)

    def parse_int(start):
        # start points at 'i'
        if data[start:start+1] != b'i':
            raise ValueError("not an int")
        end = data.find(b'e', start+1)
        if end == -1:
            raise ValueError("unterminated integer")
        num_bytes = data[start+1:end]
        if len(num_bytes) == 0:
            raise ValueError("empty integer")
        # reject leading + sign; only optional leading -
        if num_bytes[0:1] == b'-':
            if len(num_bytes) == 1:
                raise ValueError("bare - in integer")
            if num_bytes[1:2] == b'0':
                raise ValueError("-0 is not allowed")
            if not num_bytes[1:].isdigit():
                raise ValueError("invalid integer")
        else:
            if num_bytes[0:1] == b'0' and len(num_bytes) > 1:
                raise ValueError("leading zero in integer")
            if not num_bytes.isdigit():
                raise ValueError("invalid integer")
        try:
            val = int(num_bytes.decode('ascii'))
        except Exception:
            raise ValueError("invalid integer")
        return val, end+1

    def parse_str(start):
        # start points at first digit of length
        colon = data.find(b':', start)
        if colon == -1:
            raise ValueError("missing ':' in string")
        len_bytes = data[start:colon]
        if len(len_bytes) == 0:
            raise ValueError("empty length")
        if not len_bytes.isdigit():
            raise ValueError("non-digit in length")
        if len(len_bytes) > 1 and len_bytes[0:1] == b'0':
            raise ValueError("leading zero in length")
        length = int(len_bytes.decode('ascii'))
        start_content = colon + 1
        end_content = start_content + length
        if end_content > n:
            raise ValueError("string length longer than available data")
        return data[start_content:end_content], end_content

    def parse_any(start):
        if start >= n:
            raise ValueError("unexpected end")
        c = data[start:start+1]
        if c == b'i':
            return parse_int(start)
        if c.isdigit():
            return parse_str(start)
        if c == b'l':
            idx = start + 1
            lst = []
            while True:
                if idx >= n:
                    raise ValueError("unterminated list")
                if data[idx:idx+1] == b'e':
                    return lst, idx+1
                val, idx = parse_any(idx)
                lst.append(val)
        if c == b'd':
            idx = start + 1
            d = {}
            while True:
                if idx >= n:
                    raise ValueError("unterminated dict")
                if data[idx:idx+1] == b'e':
                    return d, idx+1
                # keys must be byte strings
                key, idx2 = parse_str(idx)
                if not isinstance(key, (bytes,)):
                    raise ValueError("dict key must be bytes")
                val, idx3 = parse_any(idx2)
                d[key] = val
                idx = idx3
        raise ValueError("invalid start byte")

    val, endpos = parse_any(0)
    if endpos != n:
        raise ValueError("trailing data")
    return val

import re
from typing import List, Tuple, Optional


def run_asm(src: str) -> str:
    # Parse source lines: strip comments (# to end of line), strip whitespace, skip blanks
    raw_lines = src.splitlines()
    lines: List[Tuple[int, str]] = []  # (original line number starting at 1, content)
    for i, raw in enumerate(raw_lines, start=1):
        # remove comment
        idx = raw.find('#')
        if idx != -1:
            raw = raw[:idx]
        raw = raw.strip()
        if raw == '':
            continue
        lines.append((i, raw))

    # First pass: collect labels and instructions
    labels = {}  # name -> instruction index
    instructions: List[Tuple[str, Optional[str], int]] = []  # (mnemonic, operand, src_line)

    label_re = re.compile(r'^[A-Za-z0-9_]+$')

    for ln, content in lines:
        if content.endswith(':'):
            name = content[:-1].strip()
            if not name or not label_re.match(name):
                raise ValueError(f"invalid label '{name}'")
            if name in labels:
                raise ValueError(f"duplicate label '{name}'")
            labels[name] = len(instructions)
        else:
            parts = content.split()
            mnemonic = parts[0]
            operand = None
            if len(parts) > 1:
                operand = ' '.join(parts[1:])
            instructions.append((mnemonic, operand, ln))

    # Validate mnemonics and operands; for jumps keep label name to resolve later
    VALID_ZERO = {'POP', 'DUP', 'SWAP', 'ADD', 'SUB', 'MUL', 'DIV', 'NEG', 'PRINT', 'HALT'}
    VALID_ONE_LABEL = {'JMP', 'JZ', 'JNZ'}
    all_mnemonics = VALID_ZERO.union(VALID_ONE_LABEL).union({'PUSH'})

    # We'll store resolved operands: for PUSH store int, for jumps store target index
    resolved: List[Tuple[str, Optional[object], int]] = []

    for mnemonic, operand, ln in instructions:
        if mnemonic not in all_mnemonics:
            raise ValueError(f"unknown mnemonic '{mnemonic}'")
        if mnemonic == 'PUSH':
            if operand is None:
                raise ValueError('PUSH requires an integer operand')
            # operand should be an integer literal (can be negative)
            try:
                val = int(operand)
            except Exception:
                raise ValueError('PUSH requires an integer operand')
            resolved.append((mnemonic, val, ln))
        elif mnemonic in VALID_ZERO:
            if operand is not None:
                raise ValueError(f"wrong operand count for {mnemonic}")
            resolved.append((mnemonic, None, ln))
        elif mnemonic in VALID_ONE_LABEL:
            if operand is None:
                raise ValueError(f"{mnemonic} requires a label operand")
            # leave as label name for now; will resolve after checking existence
            if not label_re.match(operand):
                # invalid label name
                raise ValueError(f"invalid label '{operand}'")
            resolved.append((mnemonic, operand, ln))
        else:
            # shouldn't happen
            raise ValueError(f"unknown mnemonic '{mnemonic}'")

    # Resolve jump labels
    for i, (mnemonic, operand, ln) in enumerate(resolved):
        if mnemonic in VALID_ONE_LABEL:
            label_name = operand  # type: ignore
            if label_name not in labels:
                raise ValueError(f"undefined label '{label_name}'")
            target = labels[label_name]
            resolved[i] = (mnemonic, target, ln)

    # Execution
    stack: List[int] = []
    output_parts: List[str] = []
    ip = 0
    n = len(resolved)

    def need(nneed: int):
        if len(stack) < nneed:
            raise ValueError('stack underflow')

    while ip < n:
        mnemonic, operand, ln = resolved[ip]
        # default next ip
        next_ip = ip + 1
        if mnemonic == 'PUSH':
            stack.append(operand)  # type: ignore
        elif mnemonic == 'POP':
            need(1)
            stack.pop()
        elif mnemonic == 'DUP':
            need(1)
            stack.append(stack[-1])
        elif mnemonic == 'SWAP':
            need(2)
            a = stack.pop()
            b = stack.pop()
            stack.append(a)
            stack.append(b)
        elif mnemonic == 'ADD':
            need(2)
            a = stack.pop()
            b = stack.pop()
            stack.append(b + a)
        elif mnemonic == 'SUB':
            need(2)
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)
        elif mnemonic == 'MUL':
            need(2)
            a = stack.pop()
            b = stack.pop()
            stack.append(b * a)
        elif mnemonic == 'DIV':
            need(2)
            a = stack.pop()
            b = stack.pop()
            if a == 0:
                raise ValueError('division by zero')
            stack.append(b // a)
        elif mnemonic == 'NEG':
            need(1)
            a = stack.pop()
            stack.append(-a)
        elif mnemonic == 'PRINT':
            need(1)
            a = stack.pop()
            output_parts.append(f"{a}\n")
        elif mnemonic == 'HALT':
            break
        elif mnemonic == 'JMP':
            target = operand  # type: ignore
            if target == n:
                break
            next_ip = target
        elif mnemonic == 'JZ':
            need(1)
            a = stack.pop()
            if a == 0:
                target = operand  # type: ignore
                if target == n:
                    break
                next_ip = target
        elif mnemonic == 'JNZ':
            need(1)
            a = stack.pop()
            if a != 0:
                target = operand  # type: ignore
                if target == n:
                    break
                next_ip = target
        else:
            raise ValueError(f"unknown mnemonic '{mnemonic}'")

        ip = next_ip

    return ''.join(output_parts)

def process_csv(text: str) -> str:
    if text is None:
        raise ValueError("empty input")
    if text == "":
        raise ValueError("empty input")

    rows = []
    cur_row = []
    cur_field_chars = []
    in_quotes = False
    i = 0
    n = len(text)

    while i < n:
        ch = text[i]
        if in_quotes:
            if ch == '"':
                # possible escaped quote or end-quote
                if i + 1 < n and text[i + 1] == '"':
                    cur_field_chars.append('"')
                    i += 2
                    continue
                else:
                    in_quotes = False
                    i += 1
                    continue
            else:
                # accept any character including newlines
                cur_field_chars.append(ch)
                i += 1
                continue
        else:
            # not in quotes
            if ch == ',':
                cur_row.append(''.join(cur_field_chars))
                cur_field_chars = []
                i += 1
                continue
            elif ch == '\r':
                # treat CR or CRLF as newline
                cur_row.append(''.join(cur_field_chars))
                cur_field_chars = []
                rows.append(cur_row)
                cur_row = []
                i += 1
                if i < n and text[i] == '\n':
                    i += 1
                continue
            elif ch == '\n':
                cur_row.append(''.join(cur_field_chars))
                cur_field_chars = []
                rows.append(cur_row)
                cur_row = []
                i += 1
                continue
            elif ch == '"':
                # start quoted field only if at start of field
                if len(cur_field_chars) == 0:
                    in_quotes = True
                    i += 1
                    continue
                else:
                    # stray quote inside unquoted field; treat as literal
                    cur_field_chars.append(ch)
                    i += 1
                    continue
            else:
                cur_field_chars.append(ch)
                i += 1
                continue

    # end while
    if in_quotes:
        raise ValueError("unterminated quoted field")

    # append last field and row
    # There are two possibilities: either we ended after a newline which already appended a row,
    # or we have data in current field/row to append
    if cur_field_chars or cur_row:
        cur_row.append(''.join(cur_field_chars))
        rows.append(cur_row)
    else:
        # if nothing was added at all, it means input ended with newline and last row already appended
        pass

    if not rows:
        raise ValueError("empty input")

    # header is first row
    header = rows[0]
    header_len = len(header)

    data_rows = rows[1:]

    # validate row lengths
    for r in data_rows:
        if len(r) != header_len:
            raise ValueError("row has wrong number of columns")

    # find status and sort columns
    status_idx = None
    sort_idx = None
    for idx, name in enumerate(header):
        if name == 'status':
            status_idx = idx
        if name == 'sort':
            sort_idx = idx

    # filter out rows where status == 'skip'
    filtered = []
    for r in data_rows:
        if status_idx is not None and r[status_idx] == 'skip':
            continue
        filtered.append(r)

    # sort if needed
    if sort_idx is not None:
        def sort_key(item):
            val = item[sort_idx]
            try:
                num = float(val)
                return (0, num)
            except Exception:
                return (1, val)

        # stable sort
        filtered = sorted(filtered, key=sort_key)

    # serialize: header + filtered rows
    def quote_field(s: str) -> str:
        need = False
        if '"' in s or ',' in s or '\n' in s or '\r' in s:
            need = True
        if need:
            return '"' + s.replace('"', '""') + '"'
        else:
            return s

    out_lines = []
    # header
    out_lines.append(','.join(quote_field(f) for f in header))
    for r in filtered:
        out_lines.append(','.join(quote_field(f) for f in r))

    result = '\n'.join(out_lines) + '\n'
    return result

import json

def encode(obj: object) -> str:
    """
    Serializes a Python object graph to a string, preserving shared references and cycles.
    """
    memo = {}  # Maps id(obj) to its index in the flat_graph
    flat_graph = []

    def _encode_recursive(o):
        obj_id = id(o)
        if obj_id in memo:
            return memo[obj_id]

        # Placeholder for the object to handle cycles
        index = len(flat_graph)
        memo[obj_id] = index
        flat_graph.append(None)

        serialized_obj = {}
        if o is None or isinstance(o, (bool, int, float, str)):
            serialized_obj['type'] = 'primitive'
            serialized_obj['value'] = o
        elif isinstance(o, list):
            serialized_obj['type'] = 'list'
            serialized_obj['value'] = [_encode_recursive(item) for item in o]
        elif isinstance(o, dict):
            if not all(isinstance(k, str) for k in o.keys()):
                raise ValueError("Dictionary keys must be strings.")
            serialized_obj['type'] = 'dict'
            serialized_obj['value'] = {k: _encode_recursive(v) for k, v in o.items()}
        else:
            raise ValueError(f"Unsupported type: {type(o).__name__}")

        flat_graph[index] = serialized_obj
        return index

    if obj is not None:
        _encode_recursive(obj)

    return json.dumps(flat_graph)

def decode(s: str) -> object:
    """
    Deserializes a string back into a Python object graph, restoring shared references and cycles.
    """
    try:
        flat_graph = json.loads(s)
    except json.JSONDecodeError:
        raise ValueError("Malformed input: Not valid JSON.")

    if not isinstance(flat_graph, list):
        raise ValueError("Malformed input: Expected a JSON list.")

    if not flat_graph:
        return None

    memo = {}  # Maps index to the reconstructed object

    # Pass 1: Create placeholder objects
    for i, serialized_obj in enumerate(flat_graph):
        if not isinstance(serialized_obj, dict) or 'type' not in serialized_obj:
            raise ValueError(f"Malformed object at index {i}")

        obj_type = serialized_obj['type']
        if obj_type == 'primitive':
            memo[i] = serialized_obj.get('value')
        elif obj_type == 'list':
            memo[i] = []
        elif obj_type == 'dict':
            memo[i] = {}
        else:
            raise ValueError(f"Unknown object type '{obj_type}' at index {i}")

    # Pass 2: Populate the placeholder objects
    for i, serialized_obj in enumerate(flat_graph):
        obj_type = serialized_obj['type']
        reconstructed_obj = memo[i]

        if obj_type == 'list':
            item_ids = serialized_obj.get('value', [])
            if not isinstance(item_ids, list):
                 raise ValueError(f"Malformed list value at index {i}")
            for item_id in item_ids:
                if not isinstance(item_id, int) or item_id not in memo:
                    raise ValueError(f"Invalid object reference '{item_id}' in list at index {i}")
                reconstructed_obj.append(memo[item_id])
        elif obj_type == 'dict':
            item_map = serialized_obj.get('value', {})
            if not isinstance(item_map, dict):
                 raise ValueError(f"Malformed dict value at index {i}")
            for key, value_id in item_map.items():
                if not isinstance(value_id, int) or value_id not in memo:
                    raise ValueError(f"Invalid object reference '{value_id}' in dict at index {i}")
                reconstructed_obj[key] = memo[value_id]

    return memo.get(0)

import re

def evaluate(expression):
    if not isinstance(expression, str):
        raise TypeError("Expression must be a string")

    # Precedence and associativity
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '%': 2, '**': 4, 'u-': 3, 'u+': 3}
    associativity = {'+': 'L', '-': 'L', '*': 'L', '/': 'L', '%': 'L', '**': 'R', 'u-': 'R', 'u+': 'R'}

    def apply_operator(operators, values):
        operator = operators.pop()
        if operator.startswith('u'): # Unary operators
            if not values:
                raise ValueError("Invalid expression: Not enough operands for unary operator")
            right = values.pop()
            if operator == 'u-':
                values.append(-right)
            # Unary plus has no effect, so we do nothing
        else: # Binary operators
            if len(values) < 2:
                raise ValueError("Invalid expression: Not enough operands for binary operator")
            right = values.pop()
            left = values.pop()
            if operator == '+':
                values.append(left + right)
            elif operator == '-':
                values.append(left - right)
            elif operator == '*':
                values.append(left * right)
            elif operator == '/':
                if right == 0:
                    raise ValueError("Division by zero")
                values.append(left / right)
            elif operator == '%':
                if right == 0:
                    raise ValueError("Modulo by zero")
                # Python's % behaves like math mod, which is what's needed.
                # a % n = a - n * floor(a/n)
                values.append(left % right)
            elif operator == '**':
                values.append(left ** right)

    tokens = re.findall(r'\d+(?:\.\d*)?|\.\d+|\*\*|[-+*/%()]|\S+', expression)

    # Check for invalid tokens
    valid_tokens = re.compile(r'^(\d+(?:\.\d*)?|\.\d+|\*\*|[-+*/%()])$')
    for t in tokens:
        if not valid_tokens.match(t):
            raise ValueError(f"Invalid token: {t}")

    values = []
    operators = []
    last_token_was_op_or_lparen = True

    for i, token in enumerate(tokens):
        if token.replace('.', '', 1).isdigit():
            if not last_token_was_op_or_lparen:
                 raise ValueError("Two adjacent operands without an operator")
            values.append(float(token))
            last_token_was_op_or_lparen = False
        elif token == '(':
            if not last_token_was_op_or_lparen and i > 0:
                raise ValueError("Operand followed by opening parenthesis")
            operators.append(token)
            last_token_was_op_or_lparen = True
        elif token == ')':
            if last_token_was_op_or_lparen and operators[-1] != '(':
                raise ValueError("Empty parentheses or trailing operator inside parentheses")
            while operators and operators[-1] != '(':
                apply_operator(operators, values)
            if not operators or operators.pop() != '(':
                raise ValueError("Mismatched parentheses")
            last_token_was_op_or_lparen = False
        else: # Operator
            if last_token_was_op_or_lparen: # Unary
                if token == '-':
                    op = 'u-'
                elif token == '+':
                    op = 'u+'
                else: # *, /, %, ** cannot be unary
                    raise ValueError(f"Invalid unary operator: {token}")
            else: # Binary
                op = token

            while (operators and operators[-1] != '(' and
                   (precedence.get(operators[-1], 0) > precedence.get(op, 0) or
                    (precedence.get(operators[-1], 0) == precedence.get(op, 0) and associativity.get(op) == 'L'))):
                apply_operator(operators, values)
            operators.append(op)
            last_token_was_op_or_lparen = True

    if last_token_was_op_or_lparen and tokens:
        raise ValueError("Trailing operator")
    if not tokens and not values:
        raise ValueError("Empty expression")

    while operators:
        if operators[-1] == '(':
            raise ValueError("Mismatched parentheses")
        apply_operator(operators, values)

    if len(values) != 1:
        raise ValueError("Invalid expression")

    return values[0]

