        apply_op()

    if len(values) != 1 or ops:
        raise ValueError("Syntax error in expression")

    return values[0]

def tokenize(expr):
    token_regex = r'\s*(\d+|[a-zA-Z_]\w*|==|!=|<=|>=|[-+*/%()<>{}=])\s*'
    tokens = re.findall(token_regex, expr)
    reconstructed = "".join(tokens)
