import threading

class Bank:
    def __init__(self):
        self._balances = {}
        self._locks = {}
        self._lock = threading.Lock()  # For creating accounts

    def create_account(self, acc_id: str) -> None:
        with self._lock:
            if acc_id in self._balances:
                raise ValueError(f"Account {acc_id} already exists")
            self._balances[acc_id] = 0.0
            self._locks[acc_id] = threading.Lock()

    def deposit(self, acc_id: str, amount: float) -> None:
        if amount <= 0:
            raise ValueError("Deposit amount must be positive")

        with self._lock:
            if acc_id not in self._balances:
                raise ValueError(f"Account {acc_id} does not exist")
            account_lock = self._locks[acc_id]

        with account_lock:
            self._balances[acc_id] += amount

    def withdraw(self, acc_id: str, amount: float) -> None:
        if amount <= 0:
            raise ValueError("Withdrawal amount must be positive")

        with self._lock:
            if acc_id not in self._balances:
                raise ValueError(f"Account {acc_id} does not exist")
            account_lock = self._locks[acc_id]

        with account_lock:
            if self._balances[acc_id] < amount:
                raise ValueError("Insufficient funds")
            self._balances[acc_id] -= amount

    def transfer(self, from_id: str, to_id: str, amount: float) -> None:
        if amount <= 0:
            raise ValueError("Transfer amount must be positive")
        if from_id == to_id:
            return

        with self._lock:
            if from_id not in self._balances:
                raise ValueError(f"Account {from_id} does not exist")
            if to_id not in self._balances:
                raise ValueError(f"Account {to_id} does not exist")

            from_lock = self._locks[from_id]
            to_lock = self._locks[to_id]

        # Deadlock avoidance
        lock_first, lock_second = (from_lock, to_lock) if from_id < to_id else (to_lock, from_lock)

        with lock_first:
            with lock_second:
                if self._balances[from_id] < amount:
                    raise ValueError("Insufficient funds for transfer")
                self._balances[from_id] -= amount
                self._balances[to_id] += amount

    def balance(self, acc_id: str) -> float:
        with self._lock:
            if acc_id not in self._balances:
                raise ValueError(f"Account {acc_id} does not exist")
            account_lock = self._locks[acc_id]

        with account_lock:
            return self._balances[acc_id]

def bencode(obj):
    if isinstance(obj, bool):
        raise ValueError(f"Unsupported type: {type(obj)}")
    if isinstance(obj, int):
        return f"i{obj}e".encode('ascii')
    elif isinstance(obj, bytes):
        return f"{len(obj)}:".encode('ascii') + obj
    elif isinstance(obj, str):
        return bencode(obj.encode('utf-8'))
    elif isinstance(obj, list):
        return b'l' + b''.join(bencode(item) for item in obj) + b'e'
    elif isinstance(obj, dict):
        if not all(isinstance(k, str) for k in obj.keys()):
            raise ValueError("Dictionary keys must be strings")

        encoded_items = []
        try:
            sorted_keys = sorted(obj.keys())
        except TypeError:
            # This can happen if keys are not comparable, though the spec implies string keys.
            # Bencode requires keys to be sorted by their byte representation.
            # We will sort by the encoded keys later.
            pass

        for k in sorted(obj.keys()):
            v = obj[k]
            encoded_key = bencode(k)
            encoded_value = bencode(v)
            encoded_items.append((encoded_key, encoded_value))

        # The spec requires sorting by the raw (bencoded) key bytes
        encoded_items.sort(key=lambda x: x[0])

        result = b'd'
        for k_encoded, v_encoded in encoded_items:
            result += k_encoded
            result += v_encoded
        result += b'e'
        return result
    else:
        raise ValueError(f"Unsupported type: {type(obj)}")

def bdecode(data):
    if not isinstance(data, bytes):
        raise TypeError("Input must be bytes")
    if not data:
        raise ValueError("Empty input")

    obj, length = _bdecode_recursive(data, 0)

    if length != len(data):
        raise ValueError("Trailing data")

    return obj

def _bdecode_recursive(data, index):
    if index >= len(data):
        raise ValueError("Unexpected end of data")

    marker = data[index:index+1]

    if marker == b'i':
        end_index = data.find(b'e', index + 1)
        if end_index == -1:
            raise ValueError("Unterminated integer")

        num_str_bytes = data[index + 1:end_index]
        if not num_str_bytes or num_str_bytes == b'-':
             raise ValueError("Invalid integer")

        if (num_str_bytes.startswith(b'0') and len(num_str_bytes) > 1) or num_str_bytes == b'-0':
            raise ValueError("Integer with leading zero")

        try:
            val = int(num_str_bytes)
            return val, end_index + 1
        except ValueError:
            raise ValueError("Invalid integer format")

    elif marker == b'l':
        index += 1
        items = []
        while index < len(data) and data[index:index+1] != b'e':
            item, index = _bdecode_recursive(data, index)
            items.append(item)

        if index >= len(data) or data[index:index+1] != b'e':
            raise ValueError("Unterminated list")

        return items, index + 1

    elif marker == b'd':
        index += 1
        items = {}
        last_key = None
        while index < len(data) and data[index:index+1] != b'e':
            key, new_index = _bdecode_recursive(data, index)
            if not isinstance(key, bytes):
                raise ValueError("Dictionary key must be bytes")

            if last_key is not None and last_key >= key:
                # While not strictly required by all decoders, it's good practice
                # to check for sorted keys to catch malformed data.
                # However, the prompt doesn't mandate this check on decode.
                pass

            value, new_index_val = _bdecode_recursive(data, new_index)
            items[key] = value
            index = new_index_val
            last_key = key

        if index >= len(data) or data[index:index+1] != b'e':
            raise ValueError("Unterminated dictionary")

        return items, index + 1

    elif marker.isdigit():
        colon_index = data.find(b':', index)
        if colon_index == -1:
            raise ValueError("Invalid string length prefix")

        len_str_bytes = data[index:colon_index]

        if len_str_bytes.startswith(b'0') and len(len_str_bytes) > 1:
            raise ValueError("String length with leading zero")

        try:
            length = int(len_str_bytes)
        except ValueError:
            raise ValueError("Invalid string length")

        start = colon_index + 1
        end = start + length

        if end > len(data):
            raise ValueError("String length exceeds data")

        return data[start:end], end

    else:
        raise ValueError(f"Unexpected byte at index {index}")

import re

def run_asm(src: str) -> str:
    # Pass 1: Find labels and clean lines
    labels = {}
    program_lines = []
    lines = src.splitlines()

    for line_num, raw_line in enumerate(lines, 1):
        line = raw_line.strip()
        if '#' in line:
            line = line[:line.find('#')].strip()

        if not line:
            continue

        if line.endswith(':'):
            label = line[:-1]
            if not re.match(r'^[a-zA-Z0-9_]+$', label):
                raise ValueError(f"Invalid label name: {label}")
            if label in labels:
                raise ValueError(f"Duplicate label: {label}")
            labels[label] = len(program_lines)
        else:
            program_lines.append(line)

    # Pass 2: Assemble the program
    instructions = []
    for line in program_lines:
        parts = line.split()
        mnemonic = parts[0].upper()
        operands = parts[1:]

        if mnemonic == 'PUSH':
            if len(operands) != 1:
                raise ValueError(f"Wrong operand count for PUSH")
            try:
                instructions.append(('PUSH', int(operands[0])))
            except ValueError:
                raise ValueError(f"Non-integer operand for PUSH: {operands[0]}")
        elif mnemonic in ['POP', 'DUP', 'SWAP', 'ADD', 'SUB', 'MUL', 'DIV', 'NEG', 'PRINT', 'HALT']:
            if len(operands) != 0:
                raise ValueError(f"Wrong operand count for {mnemonic}")
            instructions.append((mnemonic,))
        elif mnemonic in ['JMP', 'JZ', 'JNZ']:
            if len(operands) != 1:
                raise ValueError(f"Wrong operand count for {mnemonic}")
            label = operands[0]
            if label not in labels:
                raise ValueError(f"Undefined label: {label}")
            instructions.append((mnemonic, labels[label]))
        else:
            raise ValueError(f"Unknown mnemonic: {mnemonic}")

    # --- Execution ---
    stack = []
    output = ""
    pc = 0
    while 0 <= pc < len(instructions):
        instr = instructions[pc]
        mnemonic = instr[0]
        pc_updated = False

        if mnemonic == 'PUSH':
            stack.append(instr[1])
        elif mnemonic == 'POP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.pop()
        elif mnemonic == 'DUP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])
        elif mnemonic == 'SWAP':
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif mnemonic in ['ADD', 'SUB', 'MUL', 'DIV']:
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            op2 = stack.pop()
            op1 = stack.pop()
            if mnemonic == 'ADD':
                stack.append(op1 + op2)
            elif mnemonic == 'SUB':
                stack.append(op1 - op2)
            elif mnemonic == 'MUL':
                stack.append(op1 * op2)
            elif mnemonic == 'DIV':
                if op2 == 0:
                    raise ValueError("Division by zero")
                stack.append(op1 // op2)
        elif mnemonic == 'NEG':
            if not stack:
                raise ValueError("Stack underflow")
            stack[-1] = -stack[-1]
        elif mnemonic == 'PRINT':
            if not stack:
                raise ValueError("Stack underflow")
            output += str(stack.pop()) + '\n'
        elif mnemonic == 'HALT':
            break
        elif mnemonic == 'JMP':
            pc = instr[1]
            pc_updated = True
        elif mnemonic == 'JZ':
            if not stack:
                raise ValueError("Stack underflow")
            val = stack.pop()
            if val == 0:
                pc = instr[1]
                pc_updated = True
        elif mnemonic == 'JNZ':
            if not stack:
                raise ValueError("Stack underflow")
            val = stack.pop()
            if val != 0:
                pc = instr[1]
                pc_updated = True

        if not pc_updated:
            pc += 1

    return output

import csv
import io

def process_csv(text: str) -> str:
    if not text:
        raise ValueError("Empty input")

    try:
        reader = csv.reader(io.StringIO(text))
        header = next(reader)
        data = list(reader)
    except (csv.Error, StopIteration) as e:
        raise ValueError("CSV parsing error") from e

    if any(len(row) != len(header) for row in data):
        raise ValueError("Inconsistent row length")

    if 'status' in header:
        status_index = header.index('status')
        data = [row for row in data if row[status_index] != 'skip']

    if 'sort' in header:
        sort_index = header.index('sort')
        def sort_key(row):
            value = row[sort_index]
            try:
                return (0, float(value))
            except ValueError:
                return (1, value)
        data.sort(key=sort_key)

    output = io.StringIO()
    writer = csv.writer(output, quoting=csv.QUOTE_MINIMAL, lineterminator='\n')
    writer.writerow(header)
    writer.writerows(data)

    result = output.getvalue()
    if not result.endswith('\n'):
        result += '\n'

    return result

