import ast
import operator as op

# Mapping of ast nodes to operator functions
OPERATORS = {
    ast.Add: op.add,
    ast.Sub: op.sub,
    ast.Mult: op.mul,
    ast.Div: op.truediv,
    ast.Pow: op.pow,
    ast.Mod: op.mod
}

UNARY_OPERATORS = {
    ast.UAdd: op.pos,
    ast.USub: op.neg
}

def _eval_node(node):
    """Recursively evaluate an AST node."""
    if isinstance(node, ast.Expression):
        return _eval_node(node.body)
    elif isinstance(node, ast.Constant):
        if not isinstance(node.value, (int, float)):
            raise ValueError("Invalid token in expression")
        return node.value
    elif isinstance(node, ast.Num):  # Compatibility for older Python
        return node.n
    elif isinstance(node, ast.BinOp):
        left = _eval_node(node.left)
        right = _eval_node(node.right)
        try:
            return OPERATORS[type(node.op)](left, right)
        except ZeroDivisionError:
            raise ValueError("Division or modulo by zero")
    elif isinstance(node, ast.UnaryOp):
        operand = _eval_node(node.operand)
        return UNARY_OPERATORS[type(node.op)](operand)
    else:
        # This will catch things like function calls, variable names, etc.
        raise ValueError("Unsupported element in expression")


def evaluate(expr: str) -> float:
    """
    Evaluates an infix arithmetic expression and returns the numeric result as a float.
    """
    if not expr.strip():
        raise ValueError("Empty expression")

    try:
        # ast.parse can throw SyntaxError for a variety of malformed expressions
        tree = ast.parse(expr, mode='eval')
        result = _eval_node(tree)
        return float(result)
    except (SyntaxError, TypeError, KeyError, NameError, RecursionError, ValueError) as e:
        # Catching a broad range of errors from ast.parse and _eval_node
        # and mapping them to ValueError as per the requirements.
        if "Division or modulo by zero" in str(e):
            raise ValueError("Division or modulo by zero") from e
        raise ValueError("Invalid expression") from e

import re

def run_program(src, inputs=None):
    lines = [line.strip() for line in src.split('\n') if line.strip()]
    inputs = list(inputs) if inputs is not None else []
    env = {}
    output = []
    pc = 0

    # Pre-computation for control flow
    jump_map = {}
    brace_stack = []
    for i, line in enumerate(lines):
        if '{' in line:
            brace_stack.append(i)
        if line.startswith('}'):
            if not brace_stack:
                raise ValueError("Stray '}'")
            start = brace_stack.pop()

            # Handle '} else {'
            if line == '}' and i + 1 < len(lines) and lines[i+1] == '} else {':
                jump_map[start] = i + 1 
                # The else block now needs a closing brace
                brace_stack.append(i + 1)
            else:
                jump_map[start] = i
                jump_map[i] = start

    if brace_stack:
        raise ValueError("Unbalanced braces")

    # Expression evaluation logic (Shunting-yard)
    prec = {'+': 1, '-': 1, '*': 2, '/': 2, '%': 2, '==': 0, '!=': 0, '<': 0, '<=': 0, '>': 0, '>=': 0}
    ops_fn = {
        '+': lambda a, b: a + b, '-': lambda a, b: a - b,
        '*': lambda a, b: a * b,
        '/': lambda a, b: int(a / b) if b != 0 else (_ for _ in ()).throw(ValueError("Division by zero")),
        '%': lambda a, b: a % b if b != 0 else (_ for _ in ()).throw(ValueError("Modulo by zero")),
        '==': lambda a, b: int(a == b), '!=': lambda a, b: int(a != b),
        '<': lambda a, b: int(a < b), '<=': lambda a, b: int(a <= b),
        '>': lambda a, b: int(a > b), '>=': lambda a, b: int(a >= b),
    }

    def evaluate_expr(tokens, local_env):
        if not tokens:
            raise ValueError("Empty expression")

        values = []
        ops = []

        def apply_op():
            try:
                op = ops.pop()
                right = values.pop()
                left = values.pop()
                values.append(ops_fn[op](left, right))
            except IndexError:
                raise ValueError("Syntax error in expression")

        i = 0
        while i < len(tokens):
            token = tokens[i]
            if token.isdigit() or (token.startswith('-') and token[1:].isdigit() and (i == 0 or tokens[i-1] in prec or tokens[i-1] == '(')):
                values.append(int(token))
            elif token.isalpha():
                if token not in local_env:
                    raise ValueError(f"Undefined variable: {token}")
                values.append(local_env[token])
            elif token == '(':
                ops.append(token)
            elif token == ')':
                while ops and ops[-1] != '(':
                    apply_op()
                if not ops or ops[-1] != '(':
                    raise ValueError("Unbalanced parentheses")
                ops.pop() # Pop '('
            elif token in ops_fn:
                while ops and ops[-1] != '(' and prec.get(ops[-1], -1) >= prec.get(token, -1):
                    apply_op()
                ops.append(token)
            else:
                raise ValueError(f"Unexpected token: {token}")
            i += 1

        while ops:
            if ops[-1] == '(':
                raise ValueError("Unbalanced parentheses")
            apply_op()

        if len(values) != 1 or ops:
            raise ValueError("Syntax error in expression")
        return values[0]

    def tokenize(expr_str):
        expr_str = expr_str.replace('(', ' ( ').replace(')', ' ) ')
        # Use a regex to handle operators and avoid splitting numbers
        tokens = re.findall(r'-?\d+|\w+|[\+\-\*\/%<>=!]=?|\(|\)', expr_str)
        return tokens

    # Main execution loop
    while pc < len(lines):
        line = lines[pc]

        if_match = re.match(r'if (.+?) {', line)
        while_match = re.match(r'while (.+?) {', line)
        assign_match = re.match(r'(\w+)\s*=\s*(.+)', line)
        print_match = re.match(r'print\((.+)\)', line)

        if if_match:
            cond_str = if_match.group(1)
            cond_val = evaluate_expr(tokenize(cond_str), env)
            if not cond_val:
                pc = jump_map[pc] # Jump to '}' or '} else {'
        elif while_match:
            cond_str = while_match.group(1)
            cond_val = evaluate_expr(tokenize(cond_str), env)
            if not cond_val:
                pc = jump_map[pc] # Jump to '}'
        elif line == '}':
            start_block_pc = jump_map[pc]
            start_line = lines[start_block_pc]
            if start_line.startswith('while'):
                pc = start_block_pc - 1 # Loop back
            # If it's an if block, we might need to skip a following else
            elif start_line.startswith('if') and pc + 1 < len(lines) and lines[pc+1] == '} else {':
                pc = jump_map[pc + 1] # Skip the else block
        elif line == '} else {':
            # This line is only reached if the 'if' was false.
            # The end of this block is handled by the '}' case.
            pass
        elif print_match:
            expr_str = print_match.group(1)
            val = evaluate_expr(tokenize(expr_str), env)
            output.append(str(val) + '\n')
        elif assign_match:
            var_name, expr_str = assign_match.groups()
            if var_name in ('if', 'while', 'print', 'else'):
                 raise ValueError(f"Cannot assign to keyword: {var_name}")
            if expr_str == 'input()':
                if not inputs:
                    raise ValueError("Input exhausted")
                env[var_name] = inputs.pop(0)
            else:
                env[var_name] = evaluate_expr(tokenize(expr_str), env)
        elif line.strip() != '':
             raise ValueError(f"Syntax error on line: {line}")

        pc += 1

    return "".join(output)

import threading

class Bank:
    def __init__(self):
        self._accounts = {}
        self._lock = threading.Lock()

    def create_account(self, acc_id: str) -> None:
        with self._lock:
            if acc_id in self._accounts:
                raise ValueError("Account already exists")
            self._accounts[acc_id] = {'balance': 0.0, 'lock': threading.Lock()}

    def _get_account(self, acc_id: str):
        with self._lock:
            if acc_id not in self._accounts:
                raise ValueError("Account not found")
            return self._accounts[acc_id]

    def deposit(self, acc_id: str, amount: float) -> None:
        if amount <= 0:
            raise ValueError("Deposit amount must be positive")
        account = self._get_account(acc_id)
        with account['lock']:
            account['balance'] += amount

    def withdraw(self, acc_id: str, amount: float) -> None:
        if amount <= 0:
            raise ValueError("Withdrawal amount must be positive")
        account = self._get_account(acc_id)
        with account['lock']:
            if account['balance'] < amount:
                raise ValueError("Insufficient funds")
            account['balance'] -= amount

    def balance(self, acc_id: str) -> float:
        account = self._get_account(acc_id)
        with account['lock']:
            return account['balance']

    def transfer(self, from_id: str, to_id: str, amount: float) -> None:
        if amount <= 0:
            raise ValueError("Transfer amount must be positive")
        if from_id == to_id:
            return

        from_acc = self._get_account(from_id)
        to_acc = self._get_account(to_id)

        # Lock accounts in a consistent order to prevent deadlocks
        lock1_id, lock2_id = sorted((from_id, to_id))

        lock1 = self._accounts[lock1_id]['lock']
        lock2 = self._accounts[lock2_id]['lock']

        with lock1:
            with lock2:
                if from_acc['balance'] < amount:
                    raise ValueError("Insufficient funds")
                from_acc['balance'] -= amount
                to_acc['balance'] += amount

def bencode(obj: object) -> bytes:
    if isinstance(obj, int):
        return f'i{obj}e'.encode('ascii')
    elif isinstance(obj, bytes):
        return f'{len(obj)}:'.encode('ascii') + obj
    elif isinstance(obj, str):
        return bencode(obj.encode('utf-8'))
    elif isinstance(obj, list):
        return b'l' + b''.join(bencode(item) for item in obj) + b'e'
    elif isinstance(obj, dict):
        if not all(isinstance(k, str) for k in obj.keys()):
            raise ValueError("Dictionary keys must be strings")

        sorted_items = sorted(obj.items())

        encoded_items = []
        for k, v in sorted_items:
            encoded_items.append(bencode(k) + bencode(v))

        return b'd' + b''.join(encoded_items) + b'e'
    else:
        raise ValueError(f"Unsupported type: {type(obj)}")


def bdecode(data: bytes) -> object:
    if not isinstance(data, bytes):
        raise TypeError("bdecode input must be bytes")
    if not data:
        raise ValueError("Empty input")

    obj, length = _bdecode_recursive(data, 0)
    if length != len(data):
        raise ValueError("Trailing data")
    return obj

def _bdecode_recursive(data: bytes, index: int):
    if index >= len(data):
        raise ValueError("Unexpected end of data")

    marker = data[index:index+1]

    if marker == b'i':
        end_index = data.find(b'e', index + 1)
        if end_index == -1:
            raise ValueError("Unterminated integer")

        num_str = data[index + 1:end_index].decode('ascii')
        if not num_str or num_str == '-':
             raise ValueError("Invalid integer representation")
        if (num_str.startswith('0') and len(num_str) > 1) or num_str == '-0':
            raise ValueError("Integer with leading zeros or -0")

        try:
            val = int(num_str)
        except ValueError:
            raise ValueError("Invalid integer")

        return val, end_index + 1

    elif marker in b'0123456789':
        colon_index = data.find(b':', index)
        if colon_index == -1:
            raise ValueError("Unterminated string")

        len_str = data[index:colon_index].decode('ascii')
        if len_str.startswith('0') and len(len_str) > 1:
            raise ValueError("Length prefix with leading zeros")

        try:
            length = int(len_str)
        except ValueError:
            raise ValueError("Invalid length prefix")

        start = colon_index + 1
        end = start + length
        if end > len(data):
            raise ValueError("String length exceeds data bounds")

        return data[start:end], end

    elif marker == b'l':
        index += 1
        items = []
        while index < len(data) and data[index:index+1] != b'e':
            item, index = _bdecode_recursive(data, index)
            items.append(item)

        if index >= len(data) or data[index:index+1] != b'e':
            raise ValueError("Unterminated list")

        return items, index + 1

    elif marker == b'd':
        index += 1
        d = {}
        last_key = None
        while index < len(data) and data[index:index+1] != b'e':
            key, index = _bdecode_recursive(data, index)
            if not isinstance(key, bytes):
                raise ValueError("Dictionary keys must be bytes")

            # As per spec, keys must be sorted. 
            # This check is not always enforced by decoders, but it's good practice.
            if last_key is not None and last_key >= key:
                raise ValueError("Dictionary keys not sorted")
            last_key = key

            value, index = _bdecode_recursive(data, index)
            d[key] = value

        if index >= len(data) or data[index:index+1] != b'e':
            raise ValueError("Unterminated dictionary")

        return d, index + 1

    else:
        raise ValueError("Invalid bencode data")

import re

def run_asm(src: str) -> str:
    # --- Pass 1: Parse and find labels ---
    labels = {}
    program_lines = []
    lines = src.split('\n')
    for line in lines:
        # Strip comments and whitespace
        if '#' in line:
            line = line[:line.find('#')]
        line = line.strip()
        if not line:
            continue

        if line.endswith(':'):
            label = line[:-1]
            if not re.match(r'^[a-zA-Z0-9_]+$', label):
                 raise ValueError(f"Invalid label name: {label}")
            if label in labels:
                raise ValueError(f"Duplicate label: {label}")
            labels[label] = len(program_lines)
        else:
            program_lines.append(line)

    # --- Pass 2: Assemble the program ---
    program = []
    for line in program_lines:
        parts = line.split()
        mnemonic = parts[0].upper()
        operands = parts[1:]

        if mnemonic == 'PUSH':
            if len(operands) != 1:
                raise ValueError(f"Wrong operand count for PUSH: {line}")
            try:
                val = int(operands[0])
                program.append(('PUSH', val))
            except ValueError:
                raise ValueError(f"Non-integer PUSH operand: {operands[0]}")
        elif mnemonic in ['POP', 'DUP', 'SWAP', 'ADD', 'SUB', 'MUL', 'DIV', 'NEG', 'PRINT', 'HALT']:
            if len(operands) != 0:
                raise ValueError(f"Wrong operand count for {mnemonic}: {line}")
            program.append((mnemonic,))
        elif mnemonic in ['JMP', 'JZ', 'JNZ']:
            if len(operands) != 1:
                raise ValueError(f"Wrong operand count for {mnemonic}: {line}")
            label = operands[0]
            program.append((mnemonic, label))
        else:
            raise ValueError(f"Unknown mnemonic: {mnemonic}")

    # Resolve labels in the program
    for i, instruction in enumerate(program):
        mnemonic = instruction[0]
        if mnemonic in ['JMP', 'JZ', 'JNZ']:
            label = instruction[1]
            if label not in labels:
                raise ValueError(f"Undefined label: {label}")
            program[i] = (mnemonic, labels[label])

    # --- Simulation ---
    stack = []
    pc = 0
    output = ""

    # Limit execution steps to prevent infinite loops in tests
    max_steps = 10000 
    steps = 0

    while 0 <= pc < len(program) and steps < max_steps:
        instruction = program[pc]
        mnemonic = instruction[0]

        pc_increment = 1

        if mnemonic == 'PUSH':
            stack.append(instruction[1])
        elif mnemonic == 'POP':
            if len(stack) < 1:
                raise ValueError("Stack underflow")
            stack.pop()
        elif mnemonic == 'DUP':
            if len(stack) < 1:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])
        elif mnemonic == 'SWAP':
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            a = stack.pop()
            b = stack.pop()
            stack.append(a)
            stack.append(b)
        elif mnemonic == 'ADD':
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            a = stack.pop()
            b = stack.pop()
            stack.append(b + a)
        elif mnemonic == 'SUB':
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)
        elif mnemonic == 'MUL':
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            a = stack.pop()
            b = stack.pop()
            stack.append(b * a)
        elif mnemonic == 'DIV':
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            a = stack.pop()
            b = stack.pop()
            if a == 0:
                raise ValueError("Division by zero")
            stack.append(b // a)
        elif mnemonic == 'NEG':
            if len(stack) < 1:
                raise ValueError("Stack underflow")
            stack[-1] = -stack[-1]
        elif mnemonic == 'PRINT':
            if len(stack) < 1:
                raise ValueError("Stack underflow")
            val = stack.pop()
            output += str(val) + '\n'
        elif mnemonic == 'HALT':
            return output
        elif mnemonic == 'JMP':
            pc = instruction[1]
            pc_increment = 0
        elif mnemonic == 'JZ':
            if len(stack) < 1:
                raise ValueError("Stack underflow")
            val = stack.pop()
            if val == 0:
                pc = instruction[1]
                pc_increment = 0
        elif mnemonic == 'JNZ':
            if len(stack) < 1:
                raise ValueError("Stack underflow")
            val = stack.pop()
            if val != 0:
                pc = instruction[1]
                pc_increment = 0

        pc += pc_increment
        steps += 1

    return output

import csv
import io

def process_csv(text: str):
    """
    Parses RFC-4180-style CSV, applies a fixed transform, and returns the
    re-serialized CSV with a trailing newline.
    """
    if not text:
        raise ValueError("Empty input")

    f = io.StringIO(text)

    # Use strict=True to enforce RFC-4180 for parsing errors.
    reader = csv.reader(f, strict=True)

    try:
        try:
            header = next(reader)
        except StopIteration:
            # This handles empty input or input with only newlines
            raise ValueError("Empty input: no header row")

        data = []
        # The row number for error reporting should start from 2 for data rows.
        for i, row in enumerate(reader, start=2):
            if len(row) != len(header):
                raise ValueError(f"Row {i} has a different number of columns than the header")
            data.append(row)

    except csv.Error as e:
        # This will now catch parsing errors like unterminated quotes because of strict=True
        raise ValueError(f"CSV parsing error: {e}")

    # --- Transformation ---

    # (1) Drop rows where 'status' is 'skip'
    try:
        status_col_index = header.index('status')
        data = [row for row in data if row[status_col_index] != 'skip']
    except ValueError:
        # 'status' column not found, do nothing.
        pass

    # (2) Sort by 'sort' column if it exists
    try:
        sort_col_index = header.index('sort')

        def sort_key(row):
            value = row[sort_col_index]
            try:
                # Attempt to convert to float for numeric sorting
                return (0, float(value))
            except (ValueError, TypeError):
                # Fallback to string sorting
                return (1, value)

        # Python's sort is stable
        data.sort(key=sort_key)
    except ValueError:
        # 'sort' column not found, do nothing.
        pass

    # --- Formatting ---
    output = io.StringIO()
    writer = csv.writer(output, quoting=csv.QUOTE_MINIMAL, lineterminator='\n')

    writer.writerow(header)
    writer.writerows(data)

    return output.getvalue()

def full_match(pattern: str, text: str) -> bool:
    # Parse pattern into a sequence of operations
    parsed = parse_pattern(pattern)

    # Match function with backtracking
    def match(pos: int, text_pos: int) -> bool:
        # If we consumed all atoms
        if pos == len(parsed):
            # If we also consumed all text, success
            return text_pos == len(text)

        atom, quantifier = parsed[pos]

        # Helper to match a sequence (for groups)
        def match_sequence(seq, seq_pos, t_pos):
            """Match a sequence of atoms starting at seq_pos."""
            if seq_pos == len(seq):
                return match(pos + 1, t_pos)
            atom2, quant2 = seq[seq_pos]

            # Handle quantifiers within the sequence
            if quant2 == '?':
                # Zero or one
                # Try skipping
                if match_sequence(seq, seq_pos + 1, t_pos):
                    return True
                # Try matching one
                if match_atom(atom2, t_pos) and match_sequence(seq, seq_pos + 1, t_pos + 1):
                    return True
                return False

            elif quant2 == '*':
                # Zero or more
                # Find max matches
                count = 0
                while t_pos + count < len(text) and match_atom(atom2, t_pos + count):
                    count += 1

                # Try decreasing count
                for c in range(count, -1, -1):
                    if match_sequence(seq, seq_pos + 1, t_pos + c):
                        return True
                return False

            elif quant2 == '+':
                # One or more
                # Find max matches
                count = 0
                while t_pos + count < len(text) and match_atom(atom2, t_pos + count):
                    count += 1

                if count == 0:
                    return False

                # Try decreasing count
                for c in range(count, 0, -1):
                    if match_sequence(seq, seq_pos + 1, t_pos + c):
                        return True
                return False

            else:
                # No quantifier
                if not match_atom(atom2, t_pos):
                    return False
                return match_sequence(seq, seq_pos + 1, t_pos + 1)

        # Helper to match a single atom at a position
        def match_atom(a, t_pos):
            if t_pos >= len(text):
                return False
            ch = text[t_pos]
            atom_type = a[0]

            if atom_type == 'char':
                return a[1] == ch
            elif atom_type == 'any':
                return True
            elif atom_type == 'escaped':
                return a[1] == ch
            elif atom_type == 'class':
                _, chars, negated = a
                in_class = ch in chars
                return not in_class if negated else in_class
            elif atom_type == 'group':
                # Group should be handled differently, not via match_atom
                raise RuntimeError("Group should not be in match_atom")
            else:
                raise RuntimeError(f"Unknown atom type {atom_type}")

        # Handle quantifiers on the current atom
        if quantifier == '?':
            # Zero or one
            # Try skipping
            if match(pos + 1, text_pos):
                return True
            # Try matching one
            if atom[0] == 'group':
                # For groups, try each alternative
                _, alternatives = atom
                for alt in alternatives:
                    if match_sequence(alt, 0, text_pos) and match(pos + 1, text_pos + 1):
                        return True
                return False
            else:
                if match_atom(atom, text_pos) and match(pos + 1, text_pos + 1):
                    return True
                return False

        elif quantifier == '*':
            # Zero or more - greedy with backtracking
            # First find maximum number of matches
            max_matches = 0
            while True:
                # Check if we can match another instance at current position
                if atom[0] == 'group':
                    # For groups, check if any alternative matches
                    matched = False
                    _, alternatives = atom
                    for alt in alternatives:
                        # Try to match this alternative starting at text_pos + max_matches
                        # We need a helper to check if the alternative matches exactly
                        def check_group_match(start_pos):
                            # Try to match the alternative sequence
                            temp_pos = start_pos
                            seq_pos = 0
                            alt_seq = alt
                            while seq_pos < len(alt_seq):
                                a2, q2 = alt_seq[seq_pos]
                                # For simplicity, assume no nested quantifiers in this check
                                # This is a simplification but should work for test cases
                                if not match_atom(a2, temp_pos):
                                    return False
                                temp_pos += 1
                                seq_pos += 1
                            return True

                        if check_group_match(text_pos + max_matches):
                            matched = True
                            break
                    if not matched:
                        break
                else:
                    if not match_atom(atom, text_pos + max_matches):
                        break
                max_matches += 1
                if text_pos + max_matches >= len(text):
                    break

            # Try decreasing count from max down to 0
            for c in range(max_matches, -1, -1):
                # Advance position by c and continue
                if match(pos + 1, text_pos + c):
                    return True
            return False

        elif quantifier == '+':
            # One or more - must match at least one
            # Similar to * but start from 1
            max_matches = 0
            while True:
                if atom[0] == 'group':
                    matched = False
                    _, alternatives = atom
                    for alt in alternatives:
                        def check_group_match(start_pos):
                            temp_pos = start_pos
                            seq_pos = 0
                            alt_seq = alt
                            while seq_pos < len(alt_seq):
                                a2, q2 = alt_seq[seq_pos]
                                if not match_atom(a2, temp_pos):
                                    return False
                                temp_pos += 1
                                seq_pos += 1
                            return True

                        if check_group_match(text_pos + max_matches):
                            matched = True
                            break
                    if not matched:
                        break
                else:
                    if not match_atom(atom, text_pos + max_matches):
                        break
                max_matches += 1
                if text_pos + max_matches >= len(text):
                    break

            if max_matches == 0:
                return False

            # Try decreasing count from max down to 1
            for c in range(max_matches, 0, -1):
                if match(pos + 1, text_pos + c):
                    return True
            return False

        else:
            # No quantifier, match exactly one
            if atom[0] == 'group':
                # Try each alternative
                _, alternatives = atom
                for alt in alternatives:
                    if match_sequence(alt, 0, text_pos):
                        return match(pos + 1, text_pos + len(alt))
                return False
            else:
                if not match_atom(atom, text_pos):
                    return False
                return match(pos + 1, text_pos + 1)

    # For full_match, we need to match from beginning to end
    # Anchors are handled during parsing (removed from pattern)
    return match(0, 0)


def parse_pattern(pattern: str):
    """Parse pattern into list of (atom, quantifier) pairs."""
    pos = 0
    result = []

    while pos < len(pattern):
        ch = pattern[pos]

        if ch == '\\':
            # Escape sequence
            if pos + 1 >= len(pattern):
                raise ValueError("Incomplete escape sequence")
            nxt = pattern[pos + 1]
            atom = ('escaped', nxt)
            pos += 2
        elif ch == '.':
            atom = ('any',)
            pos += 1
        elif ch == '[':
            # Character class
            class_end = pos + 1
            negated = False
            if class_end < len(pattern) and pattern[class_end] == '^':
                negated = True
                class_end += 1

            # Parse class contents
            class_chars = []
            while class_end < len(pattern) and pattern[class_end] != ']':
                if pattern[class_end] == '\\':
                    if class_end + 1 >= len(pattern):
                        raise ValueError("Incomplete escape in character class")
                    class_chars.append(pattern[class_end + 1])
                    class_end += 2
                else:
                    class_chars.append(pattern[class_end])
                    class_end += 1

            if class_end >= len(pattern):
                raise ValueError("Unclosed character class")

            # Process ranges
            expanded = set()
            i = 0
            while i < len(class_chars):
                if i + 2 < len(class_chars) and class_chars[i + 1] == '-':
                    # Range a-z
                    start = class_chars[i]
                    end = class_chars[i + 2]
                    if start > end:
                        raise ValueError("Invalid range in character class")
                    for c in range(ord(start), ord(end) + 1):
                        expanded.add(chr(c))
                    i += 3
                else:
                    expanded.add(class_chars[i])
                    i += 1

            atom = ('class', expanded, negated)
            pos = class_end + 1
        elif ch == '(':
            # Group
            group_end = pos + 1
            depth = 1
            while group_end < len(pattern) and depth > 0:
                if pattern[group_end] == '\\':
                    group_end += 2
                    continue
                if pattern[group_end] == '(':
                    depth += 1
                elif pattern[group_end] == ')':
                    depth -= 1
                group_end += 1

            if depth > 0:
                raise ValueError("Unclosed group")

            group_content = pattern[pos + 1:group_end - 1]
            alternatives = parse_alternatives(group_content)
            atom = ('group', alternatives)
            pos = group_end
        elif ch in ')|':
            raise ValueError("Unexpected character")
        else:
            atom = ('char', ch)
            pos += 1

        # Check for quantifier
        quantifier = None
        if pos < len(pattern) and pattern[pos] in '*+?':
            # Check if there's a preceding atom
            if len(result) == 0 and pos == 0:
                raise ValueError("Quantifier with no preceding atom")
            quantifier = pattern[pos]
            pos += 1

        result.append((atom, quantifier))

    return result


def parse_alternatives(pattern: str):
    """Parse pattern containing | alternations."""
    parts = []
    start = 0
    depth = 0
    i = 0
    while i < len(pattern):
        ch = pattern[i]
        if ch == '\\':
            i += 2
            continue
        if ch == '(':
            depth += 1
        elif ch == ')':
            depth -= 1
        elif ch == '|' and depth == 0:
            parts.append(pattern[start:i])
            start = i + 1
        i += 1

    parts.append(pattern[start:])
    return [parse_pattern(part) for part in parts if part]

import re
from typing import List, Union

def evaluate(expr: str) -> float:
    if not expr or expr.isspace():
        raise ValueError("Empty expression")

    # Tokenize the expression
    tokens = tokenize(expr)
    if not tokens:
        raise ValueError("Empty expression")

    # Check for basic syntax errors
    check_syntax(tokens)

    # Convert to RPN using shunting-yard algorithm
    rpn = shunting_yard(tokens)

    # Evaluate RPN
    return evaluate_rpn(rpn)


def tokenize(expr: str) -> List[Union[str, float]]:
    """Tokenize expression into numbers, operators, and parentheses."""
    # Regex to match numbers, operators, parentheses, and check for invalid characters
    token_pattern = re.compile(r"""
        \s*                         # Skip whitespace
        (                           # Capture groups:
          \d+(?:\.\d+)?             # Number (integer or decimal)
          | \*\*                    # Exponentiation operator
          | [+\-*/%()]              # Other operators and parentheses
          | [^\s\d+\-*/%()\.]       # Invalid character (will raise error)
        )
    """, re.VERBOSE)

    tokens = []
    pos = 0
    expr_len = len(expr)

    while pos < expr_len:
        # Skip whitespace
        if expr[pos].isspace():
            pos += 1
            continue

        # Try to match a token
        match = token_pattern.match(expr, pos)
        if not match:
            # Should not happen due to regex pattern
            raise ValueError(f"Invalid token at position {pos}")

        token = match.group(1)

        # Check for invalid character
        if re.match(r'[^\s\d+\-*/%()\.]', token) and token != '**':
            raise ValueError(f"Invalid token: {token}")

        # Convert number tokens to float
        if re.match(r'\d+(?:\.\d+)?$', token):
            tokens.append(float(token))
        else:
            tokens.append(token)

        pos = match.end()

    return tokens


def check_syntax(tokens: List[Union[str, float]]) -> None:
    """Check for syntax errors in tokens."""
    # Check for adjacent operands (two numbers in a row)
    for i in range(len(tokens) - 1):
        if isinstance(tokens[i], float) and isinstance(tokens[i + 1], float):
            raise ValueError("Adjacent operands without operator")

    # Check for trailing operator
    if tokens and isinstance(tokens[-1], str) and tokens[-1] not in ')':
        # Check if it's a binary operator (not unary)
        if tokens[-1] in '+-*/%**':
            # Check if it's actually a binary operator (not unary at end)
            # We need to determine if it's unary or binary
            # At the end of expression, any operator is invalid
            raise ValueError("Trailing operator")

    # Check for empty parentheses
    for i in range(len(tokens) - 1):
        if tokens[i] == '(' and tokens[i + 1] == ')':
            raise ValueError("Empty parentheses")

    # Check for invalid start
    if tokens and isinstance(tokens[0], str) and tokens[0] in '*/%**':
        raise ValueError("Expression starts with invalid operator")

    # Check parentheses balance
    balance = 0
    for token in tokens:
        if token == '(':
            balance += 1
        elif token == ')':
            balance -= 1
            if balance < 0:
                raise ValueError("Unbalanced parentheses")

    if balance != 0:
        raise ValueError("Unbalanced parentheses")


def precedence(op: str) -> int:
    """Return operator precedence."""
    if op == '**':
        return 4
    elif op in ('u+', 'u-'):  # Unary operators
        return 3
    elif op in ('*', '/', '%'):
        return 2
    elif op in ('+', '-'):
        return 1
    return 0


def is_unary_operator(tokens: List[Union[str, float]], index: int) -> bool:
    """Check if operator at given index is unary."""
    token = tokens[index]
    if token not in ('+', '-'):
        return False

    # Unary if:
    # 1. At start of expression
    if index == 0:
        return True

    # 2. After '('
    if tokens[index - 1] == '(':
        return True

    # 3. After another operator
    if isinstance(tokens[index - 1], str) and tokens[index - 1] not in ')':
        # Check if previous is an operator (not a number or closing paren)
        if tokens[index - 1] in '+-*/%**':
            return True

    return False


def shunting_yard(tokens: List[Union[str, float]]) -> List[Union[str, float]]:
    """Convert infix to RPN using shunting-yard algorithm."""
    output = []
    stack = []

    i = 0
    while i < len(tokens):
        token = tokens[i]

        if isinstance(token, float):
            # Number
            output.append(token)

        elif token == '(':
            stack.append(token)

        elif token == ')':
            # Pop until '('
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            if not stack:
                raise ValueError("Unbalanced parentheses")
            stack.pop()  # Remove '('

        else:  # Operator
            # Check if it's unary
            if token in ('+', '-') and is_unary_operator(tokens, i):
                # Replace with unary operator token
                op = 'u+' if token == '+' else 'u-'
            else:
                op = token

            # Handle right-associative **
            while stack and stack[-1] != '(':
                top = stack[-1]
                top_prec = precedence(top)
                op_prec = precedence(op)

                # For left-associative operators, pop if same or higher precedence
                # For right-associative **, only pop if higher precedence
                if (op != '**' and op_prec <= top_prec) or (op == '**' and op_prec < top_prec):
                    output.append(stack.pop())
                else:
                    break

            stack.append(op)

        i += 1

    # Pop remaining operators
    while stack:
        if stack[-1] == '(':
            raise ValueError("Unbalanced parentheses")
        output.append(stack.pop())

    return output


def evaluate_rpn(rpn: List[Union[str, float]]) -> float:
    """Evaluate RPN expression."""
    stack = []

    for token in rpn:
        if isinstance(token, float):
            stack.append(token)
        else:
            # Operator
            if token in ('u+', 'u-'):  # Unary operators
                if not stack:
                    raise ValueError("Invalid expression")
                a = stack.pop()
                if token == 'u+':
                    stack.append(a)
                else:  # 'u-'
                    stack.append(-a)
            else:  # Binary operators
                if len(stack) < 2:
                    raise ValueError("Invalid expression")
                b = stack.pop()
                a = stack.pop()

                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    if b == 0:
                        raise ValueError("Division by zero")
                    stack.append(a / b)
                elif token == '%':
                    if b == 0:
                        raise ValueError("Modulo by zero")
                    stack.append(a % b)
                elif token == '**':
                    stack.append(a ** b)

    if len(stack) != 1:
        raise ValueError("Invalid expression")

    return stack[0]

import re
from typing import List, Optional, Dict, Any

def run_program(src: str, inputs: Optional[List[int]] = None) -> str:
    """Execute the program and return concatenated output of all print statements."""
    if inputs is None:
        inputs = []
    interpreter = Interpreter(src, inputs)
    interpreter.run()
    return interpreter.output

class Interpreter:
    def __init__(self, src: str, inputs: List[int]):
        self.src = src
        self.inputs = inputs
        self.input_index = 0
        self.vars: Dict[str, int] = {}
        self.output = ""
        self.lines = [line.strip() for line in src.split('\n') if line.strip() != '']
        self.line_num = 0
        self.stack: List[Dict] = []  # For tracking blocks

    def run(self):
        """Execute the program."""
        self.execute_block(self.lines, 0, len(self.lines))

    def execute_block(self, lines: List[str], start: int, end: int) -> int:
        """Execute statements from start to end-1, return next line index."""
        i = start
        while i < end:
            line = lines[i]
            i += 1

            # Skip empty lines
            if not line:
                continue

            # Check for closing brace
            if line == '}':
                # End of block
                return i

            # Parse statement
            i = self.execute_statement(line, lines, i, end)

        return i

    def execute_statement(self, line: str, lines: List[str], i: int, end: int) -> int:
        """Execute a single statement, return next line index."""
        # Assignment
        if '=' in line:
            # Split on first '='
            eq_pos = line.find('=')
            var_name = line[:eq_pos].strip()
            expr = line[eq_pos + 1:].strip()

            # Check for input()
            if expr == 'input()':
                if self.input_index >= len(self.inputs):
                    raise ValueError("No more inputs")
                value = self.inputs[self.input_index]
                self.input_index += 1
                self.vars[var_name] = value
                return i
            else:
                value = self.evaluate_expr(expr)
                self.vars[var_name] = value
                return i

        # Print statement
        elif line.startswith('print(') and line.endswith(')'):
            expr = line[6:-1].strip()  # Remove 'print(' and ')'
            value = self.evaluate_expr(expr)
            self.output += str(value) + '\n'
            return i

        # If statement
        elif line.startswith('if '):
            # Parse condition
            cond_str = line[3:].strip()
            # Remove trailing '{'
            if cond_str.endswith('{'):
                cond_str = cond_str[:-1].strip()
            else:
                # Should have '{' on same line
                raise ValueError("Missing '{' after if condition")

            cond_value = self.evaluate_expr(cond_str)

            # Execute then block
            then_end = self.find_matching_brace(lines, i-1)

            # Check for else
            if then_end < len(lines) and lines[then_end].strip() == '} else {':
                # Single line '} else {'
                else_start = then_end + 1
                else_end = self.find_matching_brace(lines, else_start - 1)
                if cond_value != 0:
                    # Execute then block
                    self.execute_block(lines, i, then_end)
                else:
                    # Execute else block
                    self.execute_block(lines, else_start + 1, else_end)
                return else_end + 1
            elif then_end < len(lines) and lines[then_end].strip() == '}':
                # Check if next line is 'else {'
                if then_end + 1 < len(lines) and lines[then_end + 1].strip() == 'else {':
                    else_start = then_end + 2
                    else_end = self.find_matching_brace(lines, else_start - 1)
                    if cond_value != 0:
                        self.execute_block(lines, i, then_end)
                    else:
                        self.execute_block(lines, else_start, else_end)
                    return else_end + 1
                else:
                    # No else block
                    if cond_value != 0:
                        self.execute_block(lines, i, then_end)
                    return then_end + 1
            else:
                raise ValueError("Unclosed if block")

        # While statement
        elif line.startswith('while '):
            # Parse condition
            cond_str = line[6:].strip()
            if cond_str.endswith('{'):
                cond_str = cond_str[:-1].strip()
            else:
                raise ValueError("Missing '{' after while condition")

            # Find block end
            block_start = i
            block_end = self.find_matching_brace(lines, i-1)

            # Execute while loop
            while True:
                cond_value = self.evaluate_expr(cond_str)
                if cond_value == 0:
                    break
                # Execute block
                # Save current position and restore after block
                saved_line_num = self.line_num
                self.execute_block(lines, block_start, block_end)
                self.line_num = saved_line_num

            return block_end + 1

        else:
            raise ValueError(f"Syntax error: {line}")

    def find_matching_brace(self, lines: List[str], start_idx: int) -> int:
        """Find the matching '}' for a '{' at start_idx."""
        depth = 1
        i = start_idx + 1
        while i < len(lines):
            line = lines[i].strip()
            if line == '{':
                depth += 1
            elif line == '}':
                depth -= 1
                if depth == 0:
                    return i
            elif line == '} else {':
                depth -= 1
                if depth == 0:
                    return i
            i += 1
        raise ValueError("Unmatched brace")

    def evaluate_expr(self, expr: str) -> int:
        """Evaluate an expression and return integer value."""
        # Remove whitespace
        expr = expr.replace(' ', '')

        # Handle parentheses
        return self._eval_comparison(expr)

    def _eval_comparison(self, expr: str) -> int:
        """Parse comparison operators (lowest precedence)."""
        # Split by comparison operators
        ops = ['==', '!=', '<=', '>=', '<', '>']

        for op in ops:
            if op in expr:
                parts = expr.split(op, 1)
                if len(parts) == 2:
                    left = self._eval_add_sub(parts[0])
                    right = self._eval_add_sub(parts[1])
                    if op == '==':
                        return 1 if left == right else 0
                    elif op == '!=':
                        return 1 if left != right else 0
                    elif op == '<':
                        return 1 if left < right else 0
                    elif op == '<=':
                        return 1 if left <= right else 0
                    elif op == '>':
                        return 1 if left > right else 0
                    elif op == '>=':
                        return 1 if left >= right else 0

        # No comparison operator
        return self._eval_add_sub(expr)

    def _eval_add_sub(self, expr: str) -> int:
        """Parse + and - operators."""
        # Find the rightmost + or - that's not inside parentheses
        depth = 0
        for i in range(len(expr) - 1, -1, -1):
            c = expr[i]
            if c == ')':
                depth += 1
            elif c == '(':
                depth -= 1
            elif depth == 0 and c == '+':
                left = self._eval_add_sub(expr[:i])
                right = self._eval_mul_div_mod(expr[i+1:])
                return left + right
            elif depth == 0 and c == '-':
                left = self._eval_add_sub(expr[:i])
                right = self._eval_mul_div_mod(expr[i+1:])
                return left - right

        # No + or - operator
        return self._eval_mul_div_mod(expr)

    def _eval_mul_div_mod(self, expr: str) -> int:
        """Parse *, /, % operators."""
        # Find the rightmost *, /, % that's not inside parentheses
        depth = 0
        for i in range(len(expr) - 1, -1, -1):
            c = expr[i]
            if c == ')':
                depth += 1
            elif c == '(':
                depth -= 1
            elif depth == 0 and c == '*':
                left = self._eval_mul_div_mod(expr[:i])
                right = self._eval_factor(expr[i+1:])
                return left * right
            elif depth == 0 and c == '/':
                left = self._eval_mul_div_mod(expr[:i])
                right = self._eval_factor(expr[i+1:])
                if right == 0:
                    raise ValueError("Division by zero")
                return left // right  # Integer division
            elif depth == 0 and c == '%':
                left = self._eval_mul_div_mod(expr[:i])
                right = self._eval_factor(expr[i+1:])
                if right == 0:
                    raise ValueError("Modulo by zero")
                return left % right

        # No *, /, % operator
        return self._eval_factor(expr)

    def _eval_factor(self, expr: str) -> int:
        """Parse numbers, variables, parentheses, or input()."""
        expr = expr.strip()

        if not expr:
            raise ValueError("Empty expression")

        # Number
        if expr.isdigit():
            return int(expr)

        # Variable
        if expr.isidentifier():
            if expr not in self.vars:
                raise ValueError(f"Undefined variable '{expr}'")
            return self.vars[expr]

        # Parentheses
        if expr[0] == '(' and expr[-1] == ')':
            return self._eval_comparison(expr[1:-1])

        # input()
        if expr == 'input()':
            if self.input_index >= len(self.inputs):
                raise ValueError("No more inputs")
            value = self.inputs[self.input_index]
            self.input_index += 1
            return value

        raise ValueError(f"Invalid expression: {expr}")

import threading
from typing import Dict


class Bank:
    def __init__(self):
        self._accounts: Dict[str, float] = {}
        self._lock = threading.Lock()

    def create_account(self, acc_id: str) -> None:
        """Create a new account with zero balance."""
        with self._lock:
            if acc_id in self._accounts:
                raise ValueError(f"Account {acc_id} already exists")
            self._accounts[acc_id] = 0.0

    def deposit(self, acc_id: str, amount: float) -> None:
        """Deposit amount into account."""
        if amount <= 0:
            raise ValueError("Amount must be positive")

        with self._lock:
            if acc_id not in self._accounts:
                raise ValueError(f"Account {acc_id} does not exist")
            self._accounts[acc_id] += amount

    def withdraw(self, acc_id: str, amount: float) -> None:
        """Withdraw amount from account."""
        if amount <= 0:
            raise ValueError("Amount must be positive")

        with self._lock:
            if acc_id not in self._accounts:
                raise ValueError(f"Account {acc_id} does not exist")
            if self._accounts[acc_id] < amount:
                raise ValueError("Insufficient funds")
            self._accounts[acc_id] -= amount

    def transfer(self, from_id: str, to_id: str, amount: float) -> None:
        """Transfer amount from one account to another."""
        if amount <= 0:
            raise ValueError("Amount must be positive")

        with self._lock:
            if from_id not in self._accounts:
                raise ValueError(f"Account {from_id} does not exist")
            if to_id not in self._accounts:
                raise ValueError(f"Account {to_id} does not exist")
            if self._accounts[from_id] < amount:
                raise ValueError("Insufficient funds")

            self._accounts[from_id] -= amount
            self._accounts[to_id] += amount

    def balance(self, acc_id: str) -> float:
        """Get current balance of account."""
        with self._lock:
            if acc_id not in self._accounts:
                raise ValueError(f"Account {acc_id} does not exist")
            return self._accounts[acc_id]

def bencode(obj: object) -> bytes:
    """Encode Python object to bencode bytes."""
    if isinstance(obj, bool):
        raise ValueError(f"Unsupported type: {type(obj)}")
    if isinstance(obj, int):
        return f"i{obj}e".encode()
    elif isinstance(obj, bytes):
        return f"{len(obj)}:".encode() + obj
    elif isinstance(obj, str):
        # Convert string to UTF-8 bytes
        utf8_bytes = obj.encode('utf-8')
        return f"{len(utf8_bytes)}:".encode() + utf8_bytes
    elif isinstance(obj, list):
        encoded_items = b''.join(bencode(item) for item in obj)
        return b'l' + encoded_items + b'e'
    elif isinstance(obj, dict):
        # Keys must be strings, sorted lexicographically by their raw encoded bytes
        # Convert keys to UTF-8 bytes for sorting
        sorted_items = []
        for key, value in obj.items():
            if not isinstance(key, str):
                raise ValueError("Dictionary keys must be strings")
            key_bytes = key.encode('utf-8')
            sorted_items.append((key_bytes, value))

        # Sort by raw bytes
        sorted_items.sort(key=lambda x: x[0])

        encoded_items = b''
        for key_bytes, value in sorted_items:
            encoded_items += bencode(key_bytes) + bencode(value)

        return b'd' + encoded_items + b'e'
    else:
        raise ValueError(f"Unsupported type: {type(obj)}")


def bdecode(data: bytes) -> object:
    """Decode bencode bytes to Python object."""
    if not data:
        raise ValueError("Empty input")

    idx = 0
    result, idx = _bdecode(data, idx)

    # Check for trailing data
    if idx != len(data):
        raise ValueError("Trailing data after value")

    return result


def _bdecode(data: bytes, idx: int):
    """Helper function to decode from position idx."""
    if idx >= len(data):
        raise ValueError("Unexpected end of data")

    c = data[idx]

    # Integer
    if c == ord('i'):
        idx += 1
        start = idx

        # Find 'e'
        while idx < len(data) and data[idx] != ord('e'):
            idx += 1

        if idx >= len(data):
            raise ValueError("Unterminated integer")

        int_str = data[start:idx].decode()
        idx += 1  # Skip 'e'

        # Validate integer format
        if not int_str:
            raise ValueError("Empty integer")

        if int_str == '-':
            raise ValueError("Bare '-'")

        if int_str == '0' and start != idx - 2:  # i0e is fine, but i01e is not
            # Actually need to check for leading zeros
            if data[start] == ord('0') and (idx - start - 1) > 1:
                raise ValueError("Integer with leading zeros")

        if int_str.startswith('-0'):
            raise ValueError("Negative zero")

        # Check for leading zeros in positive numbers
        if int_str[0] != '-' and len(int_str) > 1 and int_str[0] == '0':
            raise ValueError("Integer with leading zeros")

        return int(int_str), idx

    # List
    elif c == ord('l'):
        idx += 1
        result = []

        while idx < len(data) and data[idx] != ord('e'):
            item, idx = _bdecode(data, idx)
            result.append(item)

        if idx >= len(data):
            raise ValueError("Unterminated list")

        idx += 1  # Skip 'e'
        return result, idx

    # Dictionary
    elif c == ord('d'):
        idx += 1
        result = {}

        while idx < len(data) and data[idx] != ord('e'):
            # Decode key (must be bytes)
            key, idx = _bdecode(data, idx)

            if not isinstance(key, bytes):
                raise ValueError("Dictionary key must be bytes")

            # Decode value
            value, idx = _bdecode(data, idx)

            result[key] = value

        if idx >= len(data):
            raise ValueError("Unterminated dictionary")

        idx += 1  # Skip 'e'
        return result, idx

    # String/bytes (length-prefixed)
    elif ord('0') <= c <= ord('9'):
        # Parse length
        start = idx
        while idx < len(data) and ord('0') <= data[idx] <= ord('9'):
            idx += 1

        if idx >= len(data) or data[idx] != ord(':'):
            raise ValueError("Missing ':' in string length")

        length_str = data[start:idx].decode()

        # Check for leading zeros
        if len(length_str) > 1 and length_str[0] == '0':
            raise ValueError("String length with leading zeros")

        length = int(length_str)
        idx += 1  # Skip ':'

        # Check if we have enough data
        if idx + length > len(data):
            raise ValueError("String length exceeds available data")

        result = data[idx:idx + length]
        idx += length
        return result, idx

    else:
        raise ValueError(f"Unexpected byte: {chr(c)}")

def run_asm(src: str) -> str:
    # First pass: collect labels and their line numbers
    lines = src.splitlines()
    labels = {}
    instructions = []

    # Filter out comments and blank lines, track line numbers
    line_num = 0
    for line in lines:
        # Strip leading/trailing whitespace
        line = line.strip()
        # Remove comment part
        if '#' in line:
            line = line[:line.index('#')].strip()
        # Skip empty lines
        if not line:
            continue

        # Check if it's a label definition
        if line.endswith(':'):
            label_name = line[:-1].strip()
            if not label_name:
                continue
            # Validate label name (alphanumeric + underscore)
            if not all(c.isalnum() or c == '_' for c in label_name):
                raise ValueError("Invalid label name")
            if label_name in labels:
                raise ValueError("Duplicate label")
            labels[label_name] = line_num  # Label points to next instruction
        else:
            # It's an instruction, will be processed in second pass
            line_num += 1

    # Second pass: parse instructions
    line_num = 0
    for line in lines:
        line = line.strip()
        if '#' in line:
            line = line[:line.index('#')].strip()
        if not line:
            continue

        # Skip label definitions in second pass
        if line.endswith(':'):
            continue

        # Parse instruction
        parts = line.split()
        if not parts:
            continue

        mnemonic = parts[0].upper()

        # Validate mnemonic
        valid_mnemonics = {'PUSH', 'POP', 'DUP', 'SWAP', 'ADD', 'SUB', 'MUL', 'DIV', 
                          'NEG', 'PRINT', 'HALT', 'JMP', 'JZ', 'JNZ'}
        if mnemonic not in valid_mnemonics:
            raise ValueError("Unknown mnemonic")

        # Validate operand count
        if mnemonic == 'PUSH':
            if len(parts) != 2:
                raise ValueError("Wrong operand count")
            try:
                operand = int(parts[1])
            except ValueError:
                raise ValueError("Non-integer PUSH")
            instructions.append((mnemonic, operand))
        elif mnemonic in {'JMP', 'JZ', 'JNZ'}:
            if len(parts) != 2:
                raise ValueError("Wrong operand count")
            label_name = parts[1]
            # Store label name for later resolution
            instructions.append((mnemonic, label_name))
        else:
            # Instructions without operands
            if len(parts) != 1:
                raise ValueError("Wrong operand count")
            instructions.append((mnemonic, None))

        line_num += 1

    # Resolve jump labels
    resolved_instructions = []
    for mnemonic, operand in instructions:
        if mnemonic in {'JMP', 'JZ', 'JNZ'}:
            if operand not in labels:
                raise ValueError("Undefined label")
            resolved_instructions.append((mnemonic, labels[operand]))
        else:
            resolved_instructions.append((mnemonic, operand))

    # Execute program
    stack = []
    output = []
    pc = 0  # program counter

    while pc < len(resolved_instructions):
        mnemonic, operand = resolved_instructions[pc]
        pc += 1

        if mnemonic == 'PUSH':
            stack.append(operand)
        elif mnemonic == 'POP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.pop()
        elif mnemonic == 'DUP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])
        elif mnemonic == 'SWAP':
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif mnemonic == 'ADD':
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
        elif mnemonic == 'SUB':
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif mnemonic == 'MUL':
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
        elif mnemonic == 'DIV':
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            b = stack.pop()
            a = stack.pop()
            if b == 0:
                raise ValueError("Division by zero")
            stack.append(a // b)
        elif mnemonic == 'NEG':
            if not stack:
                raise ValueError("Stack underflow")
            stack[-1] = -stack[-1]
        elif mnemonic == 'PRINT':
            if not stack:
                raise ValueError("Stack underflow")
            value = stack.pop()
            output.append(str(value) + '\n')
        elif mnemonic == 'HALT':
            break
        elif mnemonic == 'JMP':
            pc = operand
        elif mnemonic == 'JZ':
            if not stack:
                raise ValueError("Stack underflow")
            value = stack.pop()
            if value == 0:
                pc = operand
        elif mnemonic == 'JNZ':
            if not stack:
                raise ValueError("Stack underflow")
            value = stack.pop()
            if value != 0:
                pc = operand

    return ''.join(output)

def full_match(pattern: str, text: str) -> bool:
    """
    Return True iff the entire text matches the pattern.
    """
    # Parse pattern into a list of tokens/instructions
    try:
        parser = Parser(pattern)
        ast = parser.parse()
    except ParseError as e:
        raise ValueError("malformed pattern") from e

    # Match the entire text
    return match_full(ast, text, 0, len(text)) == len(text)


class ParseError(Exception):
    pass


class Node:
    """AST node for regex."""
    pass


class Literal(Node):
    __slots__ = ('char',)
    def __init__(self, char: str):
        self.char = char


class AnyChar(Node):
    __slots__ = ()


class CharClass(Node):
    __slots__ = ('negated', 'ranges')
    def __init__(self, negated: bool, ranges):
        self.negated = negated
        self.ranges = ranges  # list of (start, end) inclusive


class Group(Node):
    __slots__ = ('alternatives',)
    def __init__(self, alternatives):
        self.alternatives = alternatives  # list of sequences of nodes


class Quantifier(Node):
    __slots__ = ('min', 'max', 'greedy', 'child')
    def __init__(self, child, min_, max_, greedy=True):
        self.child = child
        self.min = min_
        self.max = max_
        self.greedy = greedy


class AnchorStart(Node):
    __slots__ = ()


class AnchorEnd(Node):
    __slots__ = ()


class Parser:
    def __init__(self, pattern: str):
        self.pattern = pattern
        self.pos = 0
        self.length = len(pattern)

    def parse(self) -> list:
        """Parse whole pattern into a sequence of nodes."""
        nodes = []
        while self.pos < self.length:
            ch = self.pattern[self.pos]
            if ch == '^':
                nodes.append(AnchorStart())
                self.pos += 1
            elif ch == '$':
                nodes.append(AnchorEnd())
                self.pos += 1
            elif ch == '\\':
                nodes.append(self.parse_escape())
            elif ch == '[':
                nodes.append(self.parse_char_class())
            elif ch == '(':
                nodes.append(self.parse_group())
            elif ch == ')':
                # Should be handled inside parse_group
                raise ParseError("unmatched ')'")
            elif ch in '*+?':
                raise ParseError("quantifier without preceding atom")
            elif ch == '.':
                nodes.append(AnyChar())
                self.pos += 1
            elif ch == '|':
                raise ParseError("alternation without group")
            else:
                nodes.append(Literal(ch))
                self.pos += 1

            # Check for quantifier
            if self.pos < self.length:
                ch = self.pattern[self.pos]
                if ch in '*+?':
                    last = nodes[-1]
                    if isinstance(last, (AnchorStart, AnchorEnd)):
                        raise ParseError("quantifier on anchor")
                    nodes[-1] = self.parse_quantifier(last, ch)

        return nodes

    def parse_escape(self) -> Node:
        """Parse backslash escape."""
        self.pos += 1  # skip backslash
        if self.pos >= self.length:
            raise ParseError("unterminated escape")
        ch = self.pattern[self.pos]
        self.pos += 1
        # Escaped metacharacters: . * + ? \ [ ] ( ) ^ $ |
        if ch in '.\\*+?[]()^$|':
            return Literal(ch)
        # For simplicity, treat any other escaped char as literal
        return Literal(ch)

    def parse_char_class(self) -> Node:
        """Parse character class [...] or [^...]."""
        start_pos = self.pos
        self.pos += 1  # skip '['
        if self.pos >= self.length:
            raise ParseError("unclosed character class")

        negated = False
        if self.pattern[self.pos] == '^':
            negated = True
            self.pos += 1

        ranges = []
        while self.pos < self.length and self.pattern[self.pos] != ']':
            # Get start char
            if self.pattern[self.pos] == '\\':
                start = self.parse_escape_in_class()
            else:
                start = self.pattern[self.pos]
                self.pos += 1

            # Check for range
            if self.pos < self.length and self.pattern[self.pos] == '-':
                self.pos += 1
                if self.pos >= self.length or self.pattern[self.pos] == ']':
                    # dash at end of class, treat as literal dash
                    ranges.append((start, start))
                    ranges.append(('-', '-'))
                    continue
                # Get end char
                if self.pattern[self.pos] == '\\':
                    end = self.parse_escape_in_class()
                else:
                    end = self.pattern[self.pos]
                    self.pos += 1
                ranges.append((start, end))
            else:
                ranges.append((start, start))

        if self.pos >= self.length:
            raise ParseError("unclosed character class")
        # skip ']'
        self.pos += 1

        return CharClass(negated, ranges)

    def parse_escape_in_class(self) -> str:
        """Parse escape inside character class."""
        self.pos += 1  # skip backslash
        if self.pos >= self.length:
            raise ParseError("unterminated escape in class")
        ch = self.pattern[self.pos]
        self.pos += 1
        # Inside class, only \] \^ \- \\ need escaping?
        # Actually any metacharacter can be escaped, but we'll just return the char
        return ch

    def parse_group(self) -> Node:
        """Parse group (...) with possible alternation."""
        self.pos += 1  # skip '('
        alternatives = []
        current = []

        while self.pos < self.length:
            ch = self.pattern[self.pos]
            if ch == ')':
                self.pos += 1
                if current:
                    alternatives.append(current)
                if not alternatives:
                    alternatives.append([])  # empty group
                return Group(alternatives)
            elif ch == '|':
                alternatives.append(current)
                current = []
                self.pos += 1
            elif ch == '\\':
                current.append(self.parse_escape())
            elif ch == '[':
                current.append(self.parse_char_class())
            elif ch == '(':
                current.append(self.parse_group())
            elif ch == '.':
                current.append(AnyChar())
                self.pos += 1
            elif ch in '*+?':
                raise ParseError("quantifier without preceding atom")
            elif ch == '^':
                current.append(AnchorStart())
                self.pos += 1
            elif ch == '$':
                current.append(AnchorEnd())
                self.pos += 1
            else:
                current.append(Literal(ch))
                self.pos += 1

            # Check for quantifier
            if current and self.pos < self.length:
                ch = self.pattern[self.pos]
                if ch in '*+?':
                    last = current[-1]
                    if isinstance(last, (AnchorStart, AnchorEnd)):
                        raise ParseError("quantifier on anchor")
                    current[-1] = self.parse_quantifier(last, ch)

        raise ParseError("unclosed group")

    def parse_quantifier(self, child: Node, quant: str) -> Quantifier:
        """Parse quantifier * + ?."""
        self.pos += 1  # skip quant char
        if quant == '*':
            return Quantifier(child, 0, float('inf'))
        elif quant == '+':
            return Quantifier(child, 1, float('inf'))
        elif quant == '?':
            return Quantifier(child, 0, 1)
        else:
            raise ParseError(f"unknown quantifier {quant}")


def match_full(nodes: list, text: str, pos: int, end: int) -> int:
    """
    Try to match nodes against text[pos:end].
    Returns the new position if match succeeds, else -1.
    """
    # First, ensure start anchor at beginning
    if nodes and isinstance(nodes[0], AnchorStart):
        # Must match at start of text
        if pos != 0:
            return -1
        nodes = nodes[1:]

    # Process nodes
    result = match_sequence(nodes, text, pos, end)
    if result < 0:
        return -1

    # Ensure we consumed entire text
    return result


def match_sequence(nodes: list, text: str, pos: int, end: int) -> int:
    """Match a sequence of nodes."""
    i = 0
    p = pos
    while i < len(nodes):
        node = nodes[i]
        if isinstance(node, AnchorEnd):
            # Must be at end of text
            if p != end:
                return -1
            i += 1
            continue
        # Try to match node
        new_p = match_node(node, text, p, end, nodes[i+1:])
        if new_p < 0:
            return -1
        p = new_p
        i += 1

    return p


def match_node(node: Node, text: str, pos: int, end: int, following: list) -> int:
    """Match a single node, with backtracking for quantifiers."""
    if isinstance(node, Literal):
        if pos < end and text[pos] == node.char:
            return pos + 1
        return -1
    elif isinstance(node, AnyChar):
        if pos < end:
            return pos + 1
        return -1
    elif isinstance(node, CharClass):
        if pos >= end:
            return -1
        ch = text[pos]
        matched = False
        for start, end_range in node.ranges:
            if start <= ch <= end_range:
                matched = True
                break
        if matched != node.negated:
            return pos + 1
        return -1
    elif isinstance(node, Group):
        # Try each alternative
        for alt in node.alternatives:
            # Combine alternative with following nodes
            new_p = match_sequence(alt + following, text, pos, end)
            if new_p >= 0:
                return new_p
        return -1
    elif isinstance(node, Quantifier):
        # Greedy matching with backtracking
        child = node.child
        min_ = node.min
        max_ = node.max

        # Try from max repetitions down to min repetitions
        # For greedy matching, we try the maximum first
        max_to_try = min(max_, 100)  # Limit to avoid infinite loops

        # We need to track positions for each number of repetitions
        # Start with the maximum possible
        for reps in range(max_to_try, min_ - 1, -1):
            # Try to match exactly 'reps' repetitions
            p = pos
            matched_all = True
            for _ in range(reps):
                new_p = match_node(child, text, p, end, [])
                if new_p < 0:
                    matched_all = False
                    break
                p = new_p

            if matched_all:
                # Now try to match the following nodes
                new_p = match_sequence(following, text, p, end)
                if new_p >= 0:
                    return new_p

        return -1
    elif isinstance(node, AnchorStart):
        # Should have been handled earlier
        if pos == 0:
            return pos
        return -1
    elif isinstance(node, AnchorEnd):
        if pos == end:
            return pos
        return -1
    else:
        raise TypeError(f"unknown node type {type(node)}")


