def encode(obj: object) -> str:
    """Serialize object graph to string preserving shared references and cycles."""
    from typing import Any, Dict, List, Union

    # Supported types: int, float, bool, None, str, list, dict with string keys
    def check_type(o: Any) -> None:
        if o is None:
            return
        if isinstance(o, (int, float, bool, str)):
            return
        if isinstance(o, list):
            for item in o:
                check_type(item)
            return
        if isinstance(o, dict):
            for key, value in o.items():
                if not isinstance(key, str):
                    raise ValueError(f"Unsupported dict key type: {type(key)}")
                check_type(value)
            return
        raise ValueError(f"Unsupported type: {type(o)}")

    check_type(obj)

    # Serialization state
    next_id = 0
    obj_to_id: Dict[int, int] = {}  # id(obj) -> serial id
    id_to_obj: Dict[int, Any] = {}  # serial id -> object
    result_parts: List[str] = []

    def encode_value(o: Any) -> str:
        nonlocal next_id
        if o is None:
            return "null"
        if isinstance(o, bool):
            return "true" if o else "false"
        if isinstance(o, int):
            return str(o)
        if isinstance(o, float):
            # Handle infinity, nan if needed
            if o == float('inf'):
                return "Infinity"
            if o == float('-inf'):
                return "-Infinity"
            if o != o:  # nan
                return "NaN"
            return repr(o)  # Use repr for exact representation
        if isinstance(o, str):
            # Escape quotes and backslashes
            escaped = o.replace('\\', '\\\\').replace('"', '\\"')
            return f'"{escaped}"'

        # For containers, check if we've seen this object before
        obj_id = id(o)
        if obj_id in obj_to_id:
            # Reference to previously seen object
            return f'@ref{obj_to_id[obj_id]}'

        # New object - assign ID
        serial_id = next_id
        next_id += 1
        obj_to_id[obj_id] = serial_id
        id_to_obj[serial_id] = o

        if isinstance(o, list):
            items = [encode_value(item) for item in o]
            return f'@list{serial_id}[{",".join(items)}]'
        elif isinstance(o, dict):
            items = []
            for key, value in sorted(o.items()):  # Sort for deterministic output
                items.append(f'{encode_value(key)}:{encode_value(value)}')
            return f'@dict{serial_id}{{{",".join(items)}}}'
        else:
            # Should not reach here due to check_type
            raise ValueError(f"Unsupported type: {type(o)}")

    result = encode_value(obj)
    return result


def decode(s: str) -> object:
    """Deserialize string back to object graph preserving shared references and cycles."""
    from typing import Any, Dict, List

    if not s:
        raise ValueError("Empty string")

    # State for reconstruction
    id_to_obj: Dict[int, Any] = {}

    def parse_value(start: int) -> tuple[Any, int]:
        """Parse a value starting at position start, return (value, next_position)."""
        nonlocal id_to_obj

        if s[start] == 'n':  # null
            if s[start:start+4] == 'null':
                return None, start + 4
            raise ValueError(f"Invalid token at position {start}")

        if s[start] == 't':  # true
            if s[start:start+4] == 'true':
                return True, start + 4
            raise ValueError(f"Invalid token at position {start}")

        if s[start] == 'f':  # false
            if s[start:start+5] == 'false':
                return False, start + 5
            raise ValueError(f"Invalid token at position {start}")

        if s[start] == '"':  # string
            end = start + 1
            while end < len(s):
                if s[end] == '"' and s[end-1] != '\\':
                    break
                end += 1
            if end >= len(s) or s[end] != '"':
                raise ValueError(f"Unterminated string at position {start}")
            escaped = s[start+1:end]
            # Unescape
            result = []
            i = 0
            while i < len(escaped):
                if escaped[i] == '\\':
                    if i+1 >= len(escaped):
                        raise ValueError(f"Invalid escape at position {start+i+1}")
                    result.append(escaped[i+1])
                    i += 2
                else:
                    result.append(escaped[i])
                    i += 1
            return ''.join(result), end + 1

        if s[start] == '@':  # reference or container
            start += 1  # Skip '@'

            # Check if it's a reference
            if s.startswith('ref', start):
                # Parse reference ID
                start += 3  # Skip 'ref'
                end = start
                while end < len(s) and s[end].isdigit():
                    end += 1
                if end == start:
                    raise ValueError(f"Missing reference ID at position {start}")

                ref_id = int(s[start:end])
                if ref_id in id_to_obj:
                    return id_to_obj[ref_id], end
                else:
                    raise ValueError(f"Forward reference to id {ref_id}")

            # Check if it's a list
            elif s.startswith('list', start):
                start += 4  # Skip 'list'
                end = start
                while end < len(s) and s[end].isdigit():
                    end += 1
                if end == start:
                    raise ValueError(f"Missing list ID at position {start}")

                list_id = int(s[start:end])

                if s[end] != '[':
                    raise ValueError(f"Expected '[' after list ID at position {end}")
                end += 1

                # Create empty list first to handle cycles
                lst = []
                id_to_obj[list_id] = lst

                # Parse items
                if s[end] == ']':
                    return lst, end + 1

                while True:
                    item, end = parse_value(end)
                    lst.append(item)

                    if end >= len(s):
                        raise ValueError(f"Unterminated list at position {start}")

                    if s[end] == ']':
                        return lst, end + 1
                    elif s[end] == ',':
                        end += 1
                    else:
                        raise ValueError(f"Expected ',' or ']' at position {end}")

            # Check if it's a dict
            elif s.startswith('dict', start):
                start += 4  # Skip 'dict'
                end = start
                while end < len(s) and s[end].isdigit():
                    end += 1
                if end == start:
                    raise ValueError(f"Missing dict ID at position {start}")

                dict_id = int(s[start:end])

                if s[end] != '{':
                    raise ValueError(f"Expected '{{' after dict ID at position {end}")
                end += 1

                # Create empty dict first to handle cycles
                dct = {}
                id_to_obj[dict_id] = dct

                if s[end] == '}':
                    return dct, end + 1

                while True:
                    # Parse key
                    key, end = parse_value(end)
                    if not isinstance(key, str):
                        raise ValueError(f"Dict key must be string, got {type(key)}")

                    if end >= len(s) or s[end] != ':':
                        raise ValueError(f"Expected ':' after dict key at position {end}")
                    end += 1

                    # Parse value
                    value, end = parse_value(end)
                    dct[key] = value

                    if end >= len(s):
                        raise ValueError(f"Unterminated dict at position {start}")

                    if s[end] == '}':
                        return dct, end + 1
                    elif s[end] == ',':
                        end += 1
                    else:
                        raise ValueError(f"Expected ',' or '}}' at position {end}")

            else:
                raise ValueError(f"Unknown container type at position {start}")

        # Number (int or float)
        # Parse number
        end = start
        while end < len(s) and (s[end].isdigit() or s[end] in '.-+eE'):
            end += 1

        num_str = s[start:end]
        if not num_str:
            raise ValueError(f"Invalid token at position {start}")

        # Try int first, then float
        if '.' in num_str or 'e' in num_str or 'E' in num_str or num_str in ('Infinity', '-Infinity', 'NaN'):
            if num_str == 'Infinity':
                return float('inf'), end
            if num_str == '-Infinity':
                return float('-inf'), end
            if num_str == 'NaN':
                return float('nan'), end
            try:
                return float(num_str), end
            except ValueError:
                raise ValueError(f"Invalid float literal: {num_str}")
        else:
            try:
                return int(num_str), end
            except ValueError:
                raise ValueError(f"Invalid int literal: {num_str}")

    try:
        result, pos = parse_value(0)
        if pos != len(s):
            raise ValueError(f"Extra characters after parsed value at position {pos}")
        return result
    except (ValueError, IndexError) as e:
        raise ValueError(f"Malformed input: {e}")

def run_program(src: str, inputs: list | None = None) -> str:
    if inputs is None:
        inputs = []

    # Tokenizer for expressions
    import re

    class Token:
        def __init__(self, type, value):
            self.type = type
            self.value = value

        def __repr__(self):
            return f"Token({self.type}, {repr(self.value)})"

    def tokenize_expr(expr_str):
        # Token types: INT, NAME, OP, COMP, LPAREN, RPAREN
        tokens = []
        i = 0
        expr_str = expr_str.strip()
        while i < len(expr_str):
            ch = expr_str[i]
            if ch.isspace():
                i += 1
                continue
            elif ch.isdigit():
                j = i
                while j < len(expr_str) and expr_str[j].isdigit():
                    j += 1
                tokens.append(Token('INT', int(expr_str[i:j])))
                i = j
            elif ch.isalpha() or ch == '_':
                j = i
                while j < len(expr_str) and (expr_str[j].isalnum() or expr_str[j] == '_'):
                    j += 1
                tokens.append(Token('NAME', expr_str[i:j]))
                i = j
            elif ch in '()':
                tokens.append(Token('LPAREN' if ch == '(' else 'RPAREN', ch))
                i += 1
            elif ch in '*/%+-':
                tokens.append(Token('OP', ch))
                i += 1
            elif ch in '=!<>':
                # Could be =, ==, !=, <, <=, >, >=
                if ch == '=':
                    if i+1 < len(expr_str) and expr_str[i+1] == '=':
                        tokens.append(Token('COMP', '=='))
                        i += 2
                    else:
                        tokens.append(Token('OP', '='))
                        i += 1
                elif ch == '!':
                    if i+1 < len(expr_str) and expr_str[i+1] == '=':
                        tokens.append(Token('COMP', '!='))
                        i += 2
                    else:
                        raise ValueError("Unexpected token '!'")
                elif ch == '<':
                    if i+1 < len(expr_str) and expr_str[i+1] == '=':
                        tokens.append(Token('COMP', '<='))
                        i += 2
                    else:
                        tokens.append(Token('COMP', '<'))
                        i += 1
                elif ch == '>':
                    if i+1 < len(expr_str) and expr_str[i+1] == '=':
                        tokens.append(Token('COMP', '>='))
                        i += 2
                    else:
                        tokens.append(Token('COMP', '>'))
                        i += 1
                else:
                    raise ValueError(f"Unexpected char {ch}")
            else:
                raise ValueError(f"Unexpected character {ch}")
        return tokens

    # Parser for expressions using precedence climbing
    class ASTNode:
        pass

    class BinOp(ASTNode):
        def __init__(self, left, op, right):
            self.left = left
            self.op = op
            self.right = right

        def __repr__(self):
            return f"BinOp({self.left}, {self.op}, {self.right})"

    class UnaryOp(ASTNode):
        def __init__(self, op, expr):
            self.op = op
            self.expr = expr

        def __repr__(self):
            return f"UnaryOp({self.op}, {self.expr})"

    class IntLit(ASTNode):
        def __init__(self, value):
            self.value = value

        def __repr__(self):
            return f"IntLit({self.value})"

    class Var(ASTNode):
        def __init__(self, name):
            self.name = name

        def __repr__(self):
            return f"Var({self.name})"

    def parse_expr(tokens):
        # Precedence levels: 0: comparisons, 1: + -, 2: * / %, 3: primary
        precedence = {
            '==': 0, '!=': 0, '<': 0, '<=': 0, '>': 0, '>=': 0,
            '+': 1, '-': 1,
            '*': 2, '/': 2, '%': 2
        }

        def parse_primary():
            nonlocal pos
            if pos >= len(tokens):
                raise ValueError("Unexpected end of expression")
            tok = tokens[pos]
            if tok.type == 'INT':
                pos += 1
                return IntLit(tok.value)
            elif tok.type == 'NAME':
                pos += 1
                return Var(tok.name)
            elif tok.type == 'LPAREN':
                pos += 1
                expr = parse_expr_helper(0)
                if pos >= len(tokens) or tokens[pos].type != 'RPAREN':
                    raise ValueError("Missing closing parenthesis")
                pos += 1
                return expr
            else:
                raise ValueError(f"Unexpected token {tok.type} in expression")

        def parse_expr_helper(min_prec):
            nonlocal pos
            left = parse_primary()

            while pos < len(tokens):
                tok = tokens[pos]
                if tok.type == 'OP' and tok.value in precedence:
                    op = tok.value
                    prec = precedence[op]
                    if prec < min_prec:
                        break
                    pos += 1
                    right = parse_expr_helper(prec + 1)
                    left = BinOp(left, op, right)
                elif tok.type == 'COMP':
                    op = tok.value
                    prec = precedence[op]
                    if prec < min_prec:
                        break
                    pos += 1
                    right = parse_expr_helper(prec + 1)
                    left = BinOp(left, op, right)
                else:
                    break
            return left

        pos = 0
        result = parse_expr_helper(0)
        if pos != len(tokens):
            raise ValueError("Trailing tokens in expression")
        return result

    # Evaluator
    def evaluate(node, env):
        if isinstance(node, IntLit):
            return node.value
        elif isinstance(node, Var):
            if node.name not in env:
                raise ValueError(f"Undefined variable {node.name}")
            return env[node.name]
        elif isinstance(node, BinOp):
            left_val = evaluate(node.left, env)
            right_val = evaluate(node.right, env)
            op = node.op
            if op == '+':
                return left_val + right_val
            elif op == '-':
                return left_val - right_val
            elif op == '*':
                return left_val * right_val
            elif op == '/':
                if right_val == 0:
                    raise ValueError("Division by zero")
                return left_val // right_val  # integer division
            elif op == '%':
                if right_val == 0:
                    raise ValueError("Modulo by zero")
                return left_val % right_val
            elif op == '==':
                return 1 if left_val == right_val else 0
            elif op == '!=':
                return 1 if left_val != right_val else 0
            elif op == '<':
                return 1 if left_val < right_val else 0
            elif op == '<=':
                return 1 if left_val <= right_val else 0
            elif op == '>':
                return 1 if left_val > right_val else 0
            elif op == '>=':
                return 1 if left_val >= right_val else 0
            else:
                raise ValueError(f"Unknown operator {op}")
        else:
            raise ValueError(f"Unknown AST node {type(node)}")

    # Statement parser and executor
    class Statement:
        pass

    class Assign(Statement):
        def __init__(self, var, expr):
            self.var = var
            self.expr = expr

        def execute(self, env, inputs, output):
            env[self.var] = evaluate(self.expr, env)

    class InputAssign(Statement):
        def __init__(self, var):
            self.var = var

        def execute(self, env, inputs, output):
            if not inputs:
                raise ValueError("No more inputs")
            env[self.var] = inputs.pop(0)

    class Print(Statement):
        def __init__(self, expr):
            self.expr = expr

        def execute(self, env, inputs, output):
            val = evaluate(self.expr, env)
            output.append(str(val))

    class If(Statement):
        def __init__(self, cond, then_block, else_block):
            self.cond = cond
            self.then_block = then_block
            self.else_block = else_block

        def execute(self, env, inputs, output):
            cond_val = evaluate(self.cond, env)
            if cond_val != 0:
                for stmt in self.then_block:
                    stmt.execute(env, inputs, output)
            elif self.else_block:
                for stmt in self.else_block:
                    stmt.execute(env, inputs, output)

    class While(Statement):
        def __init__(self, cond, body):
            self.cond = cond
            self.body = body

        def execute(self, env, inputs, output):
            while evaluate(self.cond, env) != 0:
                for stmt in self.body:
                    stmt.execute(env, inputs, output)

    def parse_statement(line, lines, line_idx):
        line = line.strip()
        if not line:
            return None, line_idx

        # Check for block end
        if line == '}':
            return 'BLOCK_END', line_idx

        # Check for if statement
        if line.startswith('if '):
            # Parse condition up to {
            if not line.endswith('{'):
                raise ValueError("Missing '{' after if condition")
            cond_str = line[3:-1].strip()
            cond_tokens = tokenize_expr(cond_str)
            cond_expr = parse_expr(cond_tokens)

            # Parse then block
            then_block = []
            line_idx += 1
            while line_idx < len(lines):
                stmt, line_idx = parse_statement(lines[line_idx], lines, line_idx)
                if stmt == 'BLOCK_END':
                    break
                if stmt is not None:
                    then_block.append(stmt)

            # Check for else
            else_block = None
            if line_idx < len(lines):
                next_line = lines[line_idx].strip()
                if next_line == 'else {':
                    line_idx += 1
                    else_block = []
                    while line_idx < len(lines):
                        stmt, line_idx = parse_statement(lines[line_idx], lines, line_idx)
                        if stmt == 'BLOCK_END':
                            break
                        if stmt is not None:
                            else_block.append(stmt)
                elif next_line.startswith('} else {'):
                    # Handle } else { on same line
                    line_idx += 1
                    else_block = []
                    while line_idx < len(lines):
                        stmt, line_idx = parse_statement(lines[line_idx], lines, line_idx)
                        if stmt == 'BLOCK_END':
                            break
                        if stmt is not None:
                            else_block.append(stmt)

            return If(cond_expr, then_block, else_block), line_idx

        # Check for while statement
        if line.startswith('while '):
            if not line.endswith('{'):
                raise ValueError("Missing '{' after while condition")
            cond_str = line[6:-1].strip()
            cond_tokens = tokenize_expr(cond_str)
            cond_expr = parse_expr(cond_tokens)

            # Parse body
            body = []
            line_idx += 1
            while line_idx < len(lines):
                stmt, line_idx = parse_statement(lines[line_idx], lines, line_idx)
                if stmt == 'BLOCK_END':
                    break
                if stmt is not None:
                    body.append(stmt)

            return While(cond_expr, body), line_idx

        # Check for print
        if line.startswith('print(') and line.endswith(')'):
            expr_str = line[6:-1].strip()
            expr_tokens = tokenize_expr(expr_str)
            expr_ast = parse_expr(expr_tokens)
            return Print(expr_ast), line_idx

        # Check for assignment
        if '=' in line:
            parts = line.split('=', 1)
            var = parts[0].strip()
            expr_str = parts[1].strip()

            # Check for input()
            if expr_str == 'input()':
                return InputAssign(var), line_idx

            # Regular assignment
            expr_tokens = tokenize_expr(expr_str)
            expr_ast = parse_expr(expr_tokens)
            return Assign(var, expr_ast), line_idx

        raise ValueError(f"Syntax error: {line}")

    # Main execution
    lines = src.splitlines()
    # Remove empty lines and strip whitespace
    lines = [line.rstrip('\n') for line in lines]

    env = {}
    output = []
    inputs = list(inputs)  # Make a copy to pop from

    line_idx = 0
    while line_idx < len(lines):
        stmt, line_idx = parse_statement(lines[line_idx], lines, line_idx)
        if stmt is not None and stmt != 'BLOCK_END':
            stmt.execute(env, inputs, output)
        line_idx += 1

    return '\n'.join(output) + ('\n' if output else '')

import threading
from typing import Dict


class Bank:
    def __init__(self):
        self._accounts: Dict[str, float] = {}
        self._lock = threading.Lock()

    def create_account(self, acc_id: str) -> None:
        """Create a new account with zero balance."""
        with self._lock:
            if acc_id in self._accounts:
                raise ValueError(f"Account {acc_id} already exists")
            self._accounts[acc_id] = 0.0

    def deposit(self, acc_id: str, amount: float) -> None:
        """Deposit amount into account."""
        if amount <= 0:
            raise ValueError("Amount must be positive")

        with self._lock:
            if acc_id not in self._accounts:
                raise ValueError(f"Account {acc_id} does not exist")
            self._accounts[acc_id] += amount

    def withdraw(self, acc_id: str, amount: float) -> None:
        """Withdraw amount from account."""
        if amount <= 0:
            raise ValueError("Amount must be positive")

        with self._lock:
            if acc_id not in self._accounts:
                raise ValueError(f"Account {acc_id} does not exist")
            if self._accounts[acc_id] < amount:
                raise ValueError(f"Insufficient funds in account {acc_id}")
            self._accounts[acc_id] -= amount

    def transfer(self, from_id: str, to_id: str, amount: float) -> None:
        """Transfer amount from one account to another atomically."""
        if amount <= 0:
            raise ValueError("Amount must be positive")

        with self._lock:
            if from_id not in self._accounts:
                raise ValueError(f"Account {from_id} does not exist")
            if to_id not in self._accounts:
                raise ValueError(f"Account {to_id} does not exist")
            if self._accounts[from_id] < amount:
                raise ValueError(f"Insufficient funds in account {from_id}")

            self._accounts[from_id] -= amount
            self._accounts[to_id] += amount

    def balance(self, acc_id: str) -> float:
        """Get current balance of account."""
        with self._lock:
            if acc_id not in self._accounts:
                raise ValueError(f"Account {acc_id} does not exist")
            return self._accounts[acc_id]

def bencode(obj: object) -> bytes:
    """Encode Python object to bencoded bytes."""
    if isinstance(obj, int):
        if obj == 0:
            return b'i0e'
        return f'i{obj}e'.encode()
    elif isinstance(obj, bytes):
        return f'{len(obj)}:'.encode() + obj
    elif isinstance(obj, str):
        # Convert string to UTF-8 bytes
        utf8_bytes = obj.encode('utf-8')
        return f'{len(utf8_bytes)}:'.encode() + utf8_bytes
    elif isinstance(obj, list):
        encoded_items = b''.join(bencode(item) for item in obj)
        return b'l' + encoded_items + b'e'
    elif isinstance(obj, dict):
        # Keys must be strings
        for key in obj.keys():
            if not isinstance(key, str):
                raise ValueError(f"Dictionary key must be str, got {type(key)}")

        # Sort keys lexicographically by their raw encoded bytes
        sorted_items = sorted(obj.items(), key=lambda kv: kv[0].encode('utf-8'))
        encoded_items = b''
        for key, value in sorted_items:
            encoded_items += bencode(key) + bencode(value)
        return b'd' + encoded_items + b'e'
    else:
        raise ValueError(f"Cannot bencode type {type(obj)}")


def bdecode(data: bytes) -> object:
    """Decode bencoded bytes to Python object."""
    if not data:
        raise ValueError("Empty input")

    idx = 0
    length = len(data)

    def parse() -> object:
        nonlocal idx
        if idx >= length:
            raise ValueError("Unexpected end of data")

        c = data[idx:idx+1]

        # Parse integer
        if c == b'i':
            idx += 1
            start = idx
            # Find the ending 'e'
            while idx < length and data[idx:idx+1] != b'e':
                idx += 1

            if idx >= length:
                raise ValueError("Unterminated integer")

            # Extract integer string
            int_str = data[start:idx].decode('ascii')
            idx += 1  # Skip 'e'

            # Validate integer format
            if not int_str:
                raise ValueError("Empty integer")
            if int_str == '-':
                raise ValueError("Invalid integer: '-'")
            if int_str[0] == '0' and len(int_str) > 1:
                raise ValueError("Integer with leading zeros")
            if int_str == '-0':
                raise ValueError("Invalid integer: '-0'")

            return int(int_str)

        # Parse string (bytes)
        elif c in b'0123456789':
            # Parse length
            start = idx
            while idx < length and data[idx:idx+1] in b'0123456789':
                idx += 1

            if idx >= length or data[idx:idx+1] != b':':
                raise ValueError("Missing ':' in string length")

            length_str = data[start:idx].decode('ascii')
            idx += 1  # Skip ':'

            # Validate length format
            if length_str == '':
                raise ValueError("Empty length prefix")
            if length_str[0] == '0' and len(length_str) > 1:
                raise ValueError("Length with leading zeros")

            str_len = int(length_str)

            # Check if we have enough data
            if idx + str_len > length:
                raise ValueError("String length exceeds available data")

            # Extract bytes
            result = data[idx:idx+str_len]
            idx += str_len
            return result

        # Parse list
        elif c == b'l':
            idx += 1
            result = []
            while idx < length and data[idx:idx+1] != b'e':
                result.append(parse())

            if idx >= length:
                raise ValueError("Unterminated list")

            idx += 1  # Skip 'e'
            return result

        # Parse dictionary
        elif c == b'd':
            idx += 1
            result = {}
            while idx < length and data[idx:idx+1] != b'e':
                # Parse key
                key = parse()
                if not isinstance(key, bytes):
                    raise ValueError("Dictionary key must be bytes")

                # Parse value
                value = parse()
                result[key] = value

            if idx >= length:
                raise ValueError("Unterminated dictionary")

            idx += 1  # Skip 'e'
            return result

        else:
            raise ValueError(f"Unexpected byte: {c}")

    result = parse()

    # Check for trailing data
    if idx < length:
        raise ValueError("Trailing data after parsed value")

    return result

def run_asm(src: str) -> str:
    # Parse source code
    lines = src.splitlines()
    instructions = []
    labels = {}
    output_lines = []

    # First pass: collect labels and build instruction list
    for line_num, line in enumerate(lines):
        # Strip whitespace and handle comments
        line = line.strip()
        if not line or line.startswith('#'):
            continue

        # Check for label
        if line.endswith(':'):
            label_name = line[:-1].strip()
            if not label_name.replace('_', '').isalnum():
                raise ValueError(f"Invalid label name: {label_name}")
            if label_name in labels:
                raise ValueError(f"Duplicate label: {label_name}")
            labels[label_name] = len(instructions)
            continue

        # Parse instruction
        parts = line.split()
        if not parts:
            continue

        mnemonic = parts[0].upper()
        operand = None
        if len(parts) > 1:
            operand = ' '.join(parts[1:])

        instructions.append((mnemonic, operand))

    # Second pass: resolve labels and execute
    pc = 0  # program counter
    stack = []
    halted = False
    output = []

    while pc < len(instructions) and not halted:
        mnemonic, operand = instructions[pc]
        pc += 1

        try:
            if mnemonic == 'PUSH':
                if operand is None:
                    raise ValueError("PUSH requires an operand")
                try:
                    value = int(operand)
                except ValueError:
                    raise ValueError(f"Invalid integer for PUSH: {operand}")
                stack.append(value)

            elif mnemonic == 'POP':
                if not stack:
                    raise ValueError("Stack underflow")
                stack.pop()

            elif mnemonic == 'DUP':
                if not stack:
                    raise ValueError("Stack underflow")
                stack.append(stack[-1])

            elif mnemonic == 'SWAP':
                if len(stack) < 2:
                    raise ValueError("Stack underflow")
                stack[-1], stack[-2] = stack[-2], stack[-1]

            elif mnemonic == 'ADD':
                if len(stack) < 2:
                    raise ValueError("Stack underflow")
                b = stack.pop()
                a = stack.pop()
                stack.append(a + b)

            elif mnemonic == 'SUB':
                if len(stack) < 2:
                    raise ValueError("Stack underflow")
                b = stack.pop()
                a = stack.pop()
                stack.append(a - b)

            elif mnemonic == 'MUL':
                if len(stack) < 2:
                    raise ValueError("Stack underflow")
                b = stack.pop()
                a = stack.pop()
                stack.append(a * b)

            elif mnemonic == 'DIV':
                if len(stack) < 2:
                    raise ValueError("Stack underflow")
                b = stack.pop()
                a = stack.pop()
                if b == 0:
                    raise ValueError("Division by zero")
                stack.append(a // b)

            elif mnemonic == 'NEG':
                if not stack:
                    raise ValueError("Stack underflow")
                stack[-1] = -stack[-1]

            elif mnemonic == 'PRINT':
                if not stack:
                    raise ValueError("Stack underflow")
                value = stack.pop()
                output.append(str(value) + '\n')

            elif mnemonic == 'HALT':
                halted = True

            elif mnemonic == 'JMP':
                if operand is None:
                    raise ValueError("JMP requires a label")
                if operand not in labels:
                    raise ValueError(f"Undefined label: {operand}")
                pc = labels[operand]

            elif mnemonic == 'JZ':
                if operand is None:
                    raise ValueError("JZ requires a label")
                if operand not in labels:
                    raise ValueError(f"Undefined label: {operand}")
                if not stack:
                    raise ValueError("Stack underflow")
                value = stack.pop()
                if value == 0:
                    pc = labels[operand]

            elif mnemonic == 'JNZ':
                if operand is None:
                    raise ValueError("JNZ requires a label")
                if operand not in labels:
                    raise ValueError(f"Undefined label: {operand}")
                if not stack:
                    raise ValueError("Stack underflow")
                value = stack.pop()
                if value != 0:
                    pc = labels[operand]

            else:
                raise ValueError(f"Unknown mnemonic: {mnemonic}")

        except ValueError as e:
            raise ValueError(f"Error executing {mnemonic}: {str(e)}")

    return ''.join(output)

def process_csv(text: str) -> str:
    """Parse RFC-4180 CSV, apply transformations, and re-serialize."""
    if not text:
        raise ValueError("Empty input")

    # Parse CSV
    rows = []
    i = 0
    n = len(text)

    def parse_field() -> str:
        """Parse a single CSV field."""
        nonlocal i
        if i >= n:
            return ""

        if text[i] == '"':
            # Quoted field
            i += 1  # Skip opening quote
            field_chars = []
            while i < n:
                if text[i] == '"':
                    if i + 1 < n and text[i + 1] == '"':
                        # Escaped quote
                        field_chars.append('"')
                        i += 2
                    else:
                        # Closing quote
                        i += 1
                        # Skip to comma or newline
                        while i < n and text[i] != ',' and text[i] != '\n':
                            if text[i] == '"':
                                # Should not have unescaped quote after closing
                                raise ValueError("Unescaped quote in field")
                            i += 1
                        break
                else:
                    field_chars.append(text[i])
                    i += 1
            else:
                # Reached end of input without closing quote
                raise ValueError("Unterminated quoted field")
            return ''.join(field_chars)
        else:
            # Unquoted field
            start = i
            while i < n and text[i] != ',' and text[i] != '\n':
                i += 1
            return text[start:i]

    def parse_row() -> list[str]:
        """Parse a single CSV row."""
        nonlocal i
        row = []
        while True:
            field = parse_field()
            row.append(field)

            if i >= n or text[i] == '\n':
                if i < n and text[i] == '\n':
                    i += 1  # Skip newline
                break
            elif text[i] == ',':
                i += 1  # Skip comma
            else:
                # Should not happen
                break
        return row

    # Parse all rows
    while i < n:
        row = parse_row()
        if row:  # Skip empty rows (e.g., trailing newline)
            rows.append(row)

    if not rows:
        raise ValueError("No rows found")

    # Header is first row
    header = rows[0]
    header_len = len(header)

    # Validate all rows have same column count as header
    for idx, row in enumerate(rows):
        if len(row) != header_len:
            raise ValueError(f"Row {idx} has different column count than header")

    # Data rows are everything after header
    data_rows = rows[1:]

    # TRANSFORMATIONS

    # 1. Filter by 'status' column if it exists
    if 'status' in header:
        status_idx = header.index('status')
        filtered_rows = []
        for row in data_rows:
            if row[status_idx] != 'skip':
                filtered_rows.append(row)
        data_rows = filtered_rows

    # 2. Sort by 'sort' column if it exists
    if 'sort' in header and data_rows:
        sort_idx = header.index('sort')

        def sort_key(row):
            value = row[sort_idx]
            try:
                # Try to parse as float
                return (0, float(value))  # 0 for numeric group
            except ValueError:
                return (1, value)  # 1 for non-numeric group

        # Stable sort
        data_rows.sort(key=sort_key)

    # FORMAT: Re-serialize as CSV
    result_rows = []

    def needs_quoting(field: str) -> bool:
        """Check if a field needs to be quoted."""
        return ',' in field or '"' in field or '\n' in field

    def serialize_field(field: str) -> str:
        """Serialize a single field with proper quoting."""
        if needs_quoting(field):
            # Escape quotes by doubling them
            escaped = field.replace('"', '""')
            return f'"{escaped}"'
        return field

    # Add header
    result_rows.append(','.join(serialize_field(f) for f in header))

    # Add data rows
    for row in data_rows:
        result_rows.append(','.join(serialize_field(f) for f in row))

    # Join with newlines and add trailing newline
    return '\n'.join(result_rows) + '\n'
